export const questions: Question[] = [
  { id: "y2fg3-001", topicRef: "y2fg3", topicTitle: "Composite Functions 20", difficulty: "Standard", questionText: "\\( f(x) = \\dfrac{1}{x} \\) \\((x \\ne 0)\\) and \\( g(x) = 2x + 5 \\), \\(x \\in \\mathbb R\\). Solve the equation \\( gf(x) = 6 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( gf(x) \\).", workingLatex: "gf(x) = g\\!\\left(\\tfrac{1}{x}\\right) = 2\\cdot\\tfrac{1}{x} + 5 = \\tfrac{2}{x} + 5", explanation: "Apply \\(f\\) first, then \\(g\\): substitute \\(\\tfrac{1}{x}\\) into \\(g\\)." }, { stepNumber: 2, description: "Set equal to 6.", workingLatex: "\\tfrac{2}{x} + 5 = 6", explanation: "" }, { stepNumber: 3, description: "Isolate \\(\\tfrac{2}{x}\\).", workingLatex: "\\tfrac{2}{x} = 1", explanation: "Subtract 5 from both sides." }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "x = 2", explanation: "Reciprocate or cross-multiply." } ], finalAnswer: "\\( x = 2 \\)." } },
  // ── Basic fg and gf ────
  { id: "y2fg3-002", topicRef: "y2fg3", topicTitle: "Composite Functions 01", difficulty: "Foundation", questionText: "\\( f(x) = 2x + 1 \\) and \\( g(x) = 3x - 4 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 23 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g(x)\\) into \\(f\\).", workingLatex: "fg(x) = f(3x - 4) = 2(3x - 4) + 1", explanation: "Apply \\(g\\) first (right-to-left), then feed the output \\(3x - 4\\) into \\(f\\). Keep the bracket visible until the next step." }, { stepNumber: 2, description: "Expand and simplify the composite.", workingLatex: "2(3x - 4) + 1 = 6x - 8 + 1 = 6x - 7", explanation: "Distribute the 2 through the bracket; combine the constants \\(-8\\) and \\(+1\\)." }, { stepNumber: 3, description: "Set the composite equal to 23.", workingLatex: "6x - 7 = 23", explanation: "" }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "6x = 30 \\Rightarrow x = 5", explanation: "Add 7, then divide by 6. Check: \\(g(5) = 11\\); \\(f(11) = 23\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 5 \\)." } },
  { id: "y2fg3-003", topicRef: "y2fg3", topicTitle: "Composite Functions 02", difficulty: "Foundation", questionText: "\\( f(x) = x^2 \\) and \\( g(x) = x + 5 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 9 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = f(x + 5) = (x + 5)^2", explanation: "Substitute \\(g(x) = x + 5\\) as the input to \\(f\\)." }, { stepNumber: 2, description: "Set the composite equal to 9.", workingLatex: "(x + 5)^2 = 9", explanation: "" }, { stepNumber: 3, description: "Take square roots.", workingLatex: "x + 5 = \\pm 3", explanation: "Both signs satisfy the squared equation — keep both branches." }, { stepNumber: 4, description: "Solve each branch.", workingLatex: "x = -2 \\;\\text{ or }\\; x = -8", explanation: "Subtract 5 in each case." } ], finalAnswer: "\\( x = -2 \\) or \\( x = -8 \\)." } },
  { id: "y2fg3-004", topicRef: "y2fg3", topicTitle: "Composite Functions 03", difficulty: "Foundation", questionText: "Given \\( f(x) = x^2 \\) and \\( g(x) = \\sqrt{x} \\) for \\(x \\ge 0\\), find \\( fg(x) \\) and \\( gf(x) \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\( fg(x) \\) by substituting \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(\\sqrt{x}) = (\\sqrt{x})^2", explanation: "Apply \\(g\\) first (right-to-left); then feed \\(\\sqrt{x}\\) into \\(f\\), which squares its input." }, { stepNumber: 2, description: "Simplify using the inverse relationship.", workingLatex: "(\\sqrt{x})^2 = x \\;\\;(x \\ge 0)", explanation: "Squaring undoes the principal square root for non-negative inputs. So \\(fg(x) = x\\)." }, { stepNumber: 3, description: "Form \\( gf(x) \\) by substituting \\(f\\) into \\(g\\).", workingLatex: "gf(x) = g(x^2) = \\sqrt{x^2}", explanation: "Apply \\(f\\) first to get \\(x^2\\); then take its principal square root. \\(x^2 \\ge 0\\), so the inner square root is always defined." }, { stepNumber: 4, description: "Simplify the principal square root.", workingLatex: "\\sqrt{x^2} = |x|", explanation: "The principal square root removes the sign — the symbol \\(\\sqrt{\\;}\\) always returns the non-negative root." }, { stepNumber: 5, description: "Restrict to the given domain.", workingLatex: "|x| = x \\;\\;(x \\ge 0)", explanation: "On \\(x \\ge 0\\), \\(|x|\\) coincides with \\(x\\), so \\(gf(x) = x\\) too — \\(f\\) and \\(g\\) act as mutual inverses on this domain." } ], finalAnswer: "\\( fg(x) = x \\) and \\( gf(x) = x \\) (both for \\(x \\ge 0\\))." } },
  { id: "y2fg3-005", topicRef: "y2fg3", topicTitle: "Composite Functions 21", difficulty: "Standard", questionText: "\\( f(x) = x^2 \\), \\(x \\in \\mathbb R\\), and \\( g(x) = \\dfrac{x}{x - 3} \\) \\((x \\ne 3)\\). Solve the equation \\( fg(x) = 4 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = f\\!\\left(\\tfrac{x}{x-3}\\right) = \\left(\\tfrac{x}{x-3}\\right)^2", explanation: "Substitute \\(g(x)\\) into \\(f\\) and square it." }, { stepNumber: 2, description: "Set equal to 4.", workingLatex: "\\left(\\tfrac{x}{x-3}\\right)^2 = 4", explanation: "" }, { stepNumber: 3, description: "Take square roots.", workingLatex: "\\tfrac{x}{x-3} = \\pm 2", explanation: "Both signs solve the squared equation." }, { stepNumber: 4, description: "Solve each branch.", workingLatex: "+2:\\; x = 2(x-3) \\Rightarrow x = 6;\\quad -2:\\; x = -2(x-3) \\Rightarrow 3x = 6 \\Rightarrow x = 2", explanation: "Cross-multiply, then solve linearly. Both values satisfy \\(x \\ne 3\\)." } ], finalAnswer: "\\( x = 2 \\) or \\( x = 6 \\)." } },
  { id: "y2fg3-006", topicRef: "y2fg3", topicTitle: "Composite Functions 22", difficulty: "Standard", questionText: "\\( f(x) = x^2 + 1 \\) and \\( g(x) = 3x - 2 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 50 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "quadratic"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = f(3x - 2) = (3x - 2)^2 + 1", explanation: "Substitute \\(g\\) into \\(f\\)." }, { stepNumber: 2, description: "Set equal to 50.", workingLatex: "(3x - 2)^2 + 1 = 50 \\Rightarrow (3x - 2)^2 = 49", explanation: "Subtract 1 from both sides." }, { stepNumber: 3, description: "Take square roots.", workingLatex: "3x - 2 = \\pm 7", explanation: "Both signs satisfy the squared equation." }, { stepNumber: 4, description: "Solve each branch.", workingLatex: "+7:\\; 3x = 9 \\Rightarrow x = 3;\\quad -7:\\; 3x = -5 \\Rightarrow x = -\\tfrac{5}{3}", explanation: "" } ], finalAnswer: "\\( x = 3 \\) or \\( x = -\\tfrac{5}{3} \\)." } },
  { id: "y2fg3-007", topicRef: "y2fg3", topicTitle: "Composite Functions 23", difficulty: "Standard", questionText: "\\( f(x) = \\dfrac{x^2}{16} \\) and \\( g(x) = 2x \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 5 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(2x) = \\tfrac{(2x)^2}{16}", explanation: "Apply \\(g\\) first to get \\(2x\\); \\(f\\) squares it and divides by 16. Square the whole \\(2x\\), not just the \\(x\\)." }, { stepNumber: 2, description: "Expand and simplify.", workingLatex: "\\tfrac{(2x)^2}{16} = \\tfrac{4x^2}{16} = \\tfrac{x^2}{4}", explanation: "\\((2x)^2 = 4x^2\\); cancel the factor 4." }, { stepNumber: 3, description: "Set equal to 5 and isolate \\(x^2\\).", workingLatex: "\\tfrac{x^2}{4} = 5 \\Rightarrow x^2 = 20", explanation: "Multiply both sides by 4." }, { stepNumber: 4, description: "Take square roots and simplify.", workingLatex: "x = \\pm \\sqrt{20} = \\pm 2\\sqrt{5}", explanation: "Use \\(\\sqrt{20} = \\sqrt{4 \\cdot 5} = 2\\sqrt{5}\\); both signs satisfy the squared equation." } ], finalAnswer: "\\( x = \\pm 2\\sqrt{5} \\)." } },
  { id: "y2fg3-008", topicRef: "y2fg3", topicTitle: "Composite Functions 24", difficulty: "Challenge", questionText: "\\( f(x) = \\sin x \\) and \\( g(x) = 2x - \\tfrac{\\pi}{3} \\). Solve \\( fg(x) = \\tfrac{1}{2} \\) on the interval \\( 0 \\le x \\le \\pi \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite.", workingLatex: "fg(x) = \\sin\\!\\left(2x - \\tfrac{\\pi}{3}\\right)", explanation: "Substitute \\(g\\) as the argument of sine." }, { stepNumber: 2, description: "Translate the \\(x\\)-interval to the argument's interval.", workingLatex: "0 \\le x \\le \\pi \\Rightarrow -\\tfrac{\\pi}{3} \\le 2x - \\tfrac{\\pi}{3} \\le \\tfrac{5\\pi}{3}", explanation: "Let \\(\\theta = 2x - \\tfrac{\\pi}{3}\\); track the endpoints under the linear map." }, { stepNumber: 3, description: "Find all \\(\\theta\\) in this interval with \\(\\sin\\theta = \\tfrac{1}{2}\\).", workingLatex: "\\theta = \\tfrac{\\pi}{6} \\;\\text{ or }\\; \\theta = \\tfrac{5\\pi}{6}", explanation: "Both lie in \\([-\\tfrac{\\pi}{3}, \\tfrac{5\\pi}{3}]\\). The next solutions \\(\\tfrac{\\pi}{6} + 2\\pi\\) etc. are outside." }, { stepNumber: 4, description: "Back-substitute and solve for \\(x\\).", workingLatex: "2x - \\tfrac{\\pi}{3} = \\tfrac{\\pi}{6} \\Rightarrow x = \\tfrac{\\pi}{4};\\quad 2x - \\tfrac{\\pi}{3} = \\tfrac{5\\pi}{6} \\Rightarrow x = \\tfrac{7\\pi}{12}", explanation: "Add \\(\\tfrac{\\pi}{3}\\) and divide by 2 in each case." } ], finalAnswer: "\\( x = \\tfrac{\\pi}{4} \\) or \\( x = \\tfrac{7\\pi}{12} \\)." } },
  { id: "y2fg3-009", topicRef: "y2fg3", topicTitle: "Composite Functions 04", difficulty: "Foundation", questionText: "\\( f(x) = 3x \\) and \\( g(x) = x - 1 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( gf(x) = 14 \\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Read the composite right-to-left.", workingLatex: "gf(x) = g(f(x))", explanation: "In \\(gf\\), the function written nearer to \\(x\\) (\\(f\\)) is applied first; \\(g\\) is then applied to the result." }, { stepNumber: 2, description: "Substitute \\(f(x) = 3x\\) into \\(g\\).", workingLatex: "g(3x) = (3x) - 1 = 3x - 1", explanation: "\\(g\\) subtracts 1 from whatever it is given." }, { stepNumber: 3, description: "Set the composite equal to 14.", workingLatex: "3x - 1 = 14", explanation: "The equation we now need to solve is a simple linear equation." }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "3x = 15 \\Rightarrow x = 5", explanation: "Add 1 to both sides, then divide by 3. Quick check: \\(f(5) = 15\\), \\(g(15) = 14\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 5 \\)." } },
  { id: "y2fg3-010", topicRef: "y2fg3", topicTitle: "Composite Functions 05", difficulty: "Foundation", questionText: "\\( f(x) = x + 3 \\) and \\( g(x) = 2x \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 11 \\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Read \\(fg\\) right-to-left.", workingLatex: "fg(x) = f(g(x))", explanation: "Apply \\(g\\) first, then feed the output into \\(f\\)." }, { stepNumber: 2, description: "Substitute \\(g(x) = 2x\\) into \\(f\\).", workingLatex: "f(2x) = (2x) + 3 = 2x + 3", explanation: "\\(f\\) adds 3 to its input — here the input is \\(2x\\)." }, { stepNumber: 3, description: "Set the composite equal to 11.", workingLatex: "2x + 3 = 11", explanation: "" }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "2x = 8 \\Rightarrow x = 4", explanation: "Subtract 3, then divide by 2. Check: \\(g(4) = 8\\), \\(f(8) = 11\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 4 \\)." } },
  { id: "y2fg3-011", topicRef: "y2fg3", topicTitle: "Composite Functions 06", difficulty: "Foundation", questionText: "\\( f(x) = 4x - 3 \\) and \\( g(x) = x + 2 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 9 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g(x)\\) into \\(f\\).", workingLatex: "fg(x) = f(x + 2) = 4(x + 2) - 3", explanation: "Apply \\(g\\) first (right-to-left), then feed the output \\(x + 2\\) into \\(f\\). Don't simplify yet — keep the bracket visible." }, { stepNumber: 2, description: "Expand and collect.", workingLatex: "4(x + 2) - 3 = 4x + 8 - 3 = 4x + 5", explanation: "Distribute the 4, then combine the constants \\(+8\\) and \\(-3\\)." }, { stepNumber: 3, description: "Set the composite equal to 9.", workingLatex: "4x + 5 = 9", explanation: "" }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "4x = 4 \\Rightarrow x = 1", explanation: "Subtract 5, then divide by 4. Check: \\(g(1) = 3\\), \\(f(3) = 9\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 1 \\)." } },
  { id: "y2fg3-012", topicRef: "y2fg3", topicTitle: "Composite Functions 07", difficulty: "Foundation", questionText: "\\( f(x) = x^2 \\) and \\( g(x) = x - 1 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( gf(x) = 24 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(f\\) into \\(g\\).", workingLatex: "gf(x) = g(x^2) = (x^2) - 1 = x^2 - 1", explanation: "Apply \\(f\\) first to get \\(x^2\\); \\(g\\) then subtracts 1." }, { stepNumber: 2, description: "Set the composite equal to 24.", workingLatex: "x^2 - 1 = 24", explanation: "" }, { stepNumber: 3, description: "Isolate \\(x^2\\).", workingLatex: "x^2 = 25", explanation: "Add 1 to both sides." }, { stepNumber: 4, description: "Take square roots.", workingLatex: "x = \\pm 5", explanation: "Both signs solve the squared equation; no domain restriction was given. Check: \\(f(\\pm 5) = 25\\); \\(g(25) = 24\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = \\pm 5 \\)." } },
  { id: "y2fg3-013", topicRef: "y2fg3", topicTitle: "Composite Functions 25", difficulty: "Standard", questionText: "\\( f(x) = 2x + 1 \\), \\(x \\in \\mathbb R\\), and \\( g(x) = \\sqrt{x} \\) \\((x \\ge 0)\\). Solve the equation \\( fg(x) = 17 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "square root"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(\\sqrt{x}) = 2\\sqrt{x} + 1", explanation: "Apply \\(g\\) first; \\(f\\) then doubles \\(\\sqrt{x}\\) and adds 1." }, { stepNumber: 2, description: "Note the composite's domain.", workingLatex: "\\text{Domain: } x \\ge 0", explanation: "Inherited from \\(g\\) — the square root requires a non-negative input." }, { stepNumber: 3, description: "Set the composite equal to 17 and isolate \\(\\sqrt{x}\\).", workingLatex: "2\\sqrt{x} + 1 = 17 \\Rightarrow 2\\sqrt{x} = 16 \\Rightarrow \\sqrt{x} = 8", explanation: "Subtract 1, then divide by 2 to peel off the linear wrapping." }, { stepNumber: 4, description: "Square both sides.", workingLatex: "(\\sqrt{x})^2 = 8^2 \\Rightarrow x = 64", explanation: "Squaring is valid because both sides are non-negative. Check \\(64 \\ge 0\\) — inside the domain. Verify: \\(\\sqrt{64} = 8\\); \\(2 \\cdot 8 + 1 = 17\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 64 \\)." } },
  { id: "y2fg3-014", topicRef: "y2fg3", topicTitle: "Composite Functions 26", difficulty: "Standard", questionText: "\\( f(x) = \\log_{10} x \\) \\((x > 0)\\) and \\( g(x) = 3 - x \\), \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 0 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = \\log_{10}(3 - x)", explanation: "Composite is defined where \\(3 - x > 0 \\Leftrightarrow x < 3\\)." }, { stepNumber: 2, description: "Set equal to 0.", workingLatex: "\\log_{10}(3 - x) = 0", explanation: "" }, { stepNumber: 3, description: "Convert from log form.", workingLatex: "3 - x = 10^0 = 1", explanation: "\\(\\log_{10} y = 0 \\iff y = 1\\)." }, { stepNumber: 4, description: "Solve.", workingLatex: "x = 2", explanation: "Inside the domain \\(x < 3\\)." } ], finalAnswer: "\\( x = 2 \\)." } },
  { id: "y2fg3-015", topicRef: "y2fg3", topicTitle: "Composite Functions 27", difficulty: "Standard", questionText: "\\( f(x) = 2^x \\) and \\( g(x) = x^2 + 2x \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 8 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = 2^{x^2 + 2x}", explanation: "Substitute \\(g\\) into the exponent of \\(f\\)." }, { stepNumber: 2, description: "Equate exponents.", workingLatex: "2^{x^2 + 2x} = 8 = 2^{3} \\Rightarrow x^2 + 2x = 3", explanation: "Since \\(2^a = 2^b \\iff a = b\\) (exponential is one-to-one)." }, { stepNumber: 3, description: "Rearrange and factorise.", workingLatex: "x^2 + 2x - 3 = 0 \\Rightarrow (x + 3)(x - 1) = 0", explanation: "" }, { stepNumber: 4, description: "Read off solutions.", workingLatex: "x = -3 \\;\\text{ or }\\; x = 1", explanation: "" } ], finalAnswer: "\\( x = 1 \\) or \\( x = -3 \\)." } },
  { id: "y2fg3-016", topicRef: "y2fg3", topicTitle: "Composite Functions 28", difficulty: "Standard", questionText: "\\( f(x) = 3x^3 \\) and \\( g(x) = 2x \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = gf(x) \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\( fg(x) \\).", workingLatex: "fg(x) = f(2x) = 3(2x)^3 = 24x^3", explanation: "" }, { stepNumber: 2, description: "Form \\( gf(x) \\).", workingLatex: "gf(x) = g(3x^3) = 2 \\cdot 3x^3 = 6x^3", explanation: "" }, { stepNumber: 3, description: "Set them equal.", workingLatex: "24x^3 = 6x^3 \\Rightarrow 18x^3 = 0", explanation: "" }, { stepNumber: 4, description: "Solve.", workingLatex: "x^3 = 0 \\Rightarrow x = 0", explanation: "Only one real cube root of zero." } ], finalAnswer: "\\( x = 0 \\)." } },
  { id: "y2fg3-017", topicRef: "y2fg3", topicTitle: "Composite Functions 29", difficulty: "Standard", questionText: "\\( f(x) = \\dfrac{7}{3 - x} \\) \\((x \\ne 3)\\) and \\( g(x) = x^2 + 3 \\), \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = -14 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(x^2 + 3) = \\tfrac{7}{3 - (x^2 + 3)}", explanation: "Apply \\(g\\) first to get \\(x^2 + 3\\); then place this into the denominator of \\(f\\)." }, { stepNumber: 2, description: "Simplify the denominator.", workingLatex: "3 - (x^2 + 3) = -x^2 \\Rightarrow fg(x) = \\tfrac{7}{-x^2} = -\\tfrac{7}{x^2}", explanation: "The 3 and \\(+3\\) cancel, leaving just \\(-x^2\\)." }, { stepNumber: 3, description: "Identify the composite's domain.", workingLatex: "x^2 + 3 \\ne 3 \\Leftrightarrow x \\ne 0", explanation: "The original \\(f\\) needs its denominator non-zero. Here that translates to \\(x \\ne 0\\)." }, { stepNumber: 4, description: "Set equal to \\(-14\\) and clean up signs.", workingLatex: "-\\tfrac{7}{x^2} = -14 \\Rightarrow \\tfrac{7}{x^2} = 14", explanation: "Multiply both sides by \\(-1\\) for convenience." }, { stepNumber: 5, description: "Cross-multiply and solve.", workingLatex: "7 = 14 x^2 \\Rightarrow x^2 = \\tfrac{1}{2}", explanation: "Move \\(x^2\\) up by multiplying both sides by \\(x^2/14\\)." }, { stepNumber: 6, description: "Take square roots.", workingLatex: "x = \\pm \\tfrac{1}{\\sqrt{2}} = \\pm \\tfrac{\\sqrt{2}}{2}", explanation: "Both values are non-zero, so both lie inside the domain. Rationalise by multiplying numerator and denominator by \\(\\sqrt{2}\\)." } ], finalAnswer: "\\( x = \\pm \\tfrac{\\sqrt{2}}{2} \\) (equivalently \\(\\pm \\tfrac{1}{\\sqrt{2}}\\))." } },
  { id: "y2fg3-018", topicRef: "y2fg3", topicTitle: "Composite Functions 30", difficulty: "Standard", questionText: "\\( f(x) = 3x - 4 \\) and \\( g(x) = 2x + 5 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( gf(x) = 6 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(f(x)\\) into \\(g\\).", workingLatex: "gf(x) = g(3x - 4) = 2(3x - 4) + 5", explanation: "Apply \\(f\\) first; \\(g\\) then doubles its input and adds 5." }, { stepNumber: 2, description: "Expand and simplify.", workingLatex: "2(3x - 4) + 5 = 6x - 8 + 5 = 6x - 3", explanation: "Distribute the 2 through the bracket and combine constants." }, { stepNumber: 3, description: "Set equal to 6.", workingLatex: "6x - 3 = 6", explanation: "" }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "6x = 9 \\Rightarrow x = \\tfrac{3}{2}", explanation: "Add 3, then divide by 6. Check: \\(f(\\tfrac{3}{2}) = \\tfrac{9}{2} - 4 = \\tfrac{1}{2}\\); \\(g(\\tfrac{1}{2}) = 1 + 5 = 6\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = \\tfrac{3}{2} \\)." } },
  // ── ff (self-composition) ────
  { id: "y2fg3-019", topicRef: "y2fg3", topicTitle: "Composite Functions 31", difficulty: "Challenge", questionText: "\\( f(x) = ax + b \\) with \\(a > 0\\). Given that \\( ff(x) = 9x + 4 \\) for all real \\(x\\), find the values of \\(a\\) and \\(b\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(ff(x)\\).", workingLatex: "ff(x) = f(ax + b) = a(ax + b) + b = a^2 x + (ab + b)", explanation: "Substitute \\(f\\) into itself; collect coefficients of \\(x\\) and constants." }, { stepNumber: 2, description: "Factor the constant term.", workingLatex: "ff(x) = a^2 x + b(a + 1)", explanation: "" }, { stepNumber: 3, description: "Match coefficients with \\(9x + 4\\).", workingLatex: "a^2 = 9 \\quad\\text{and}\\quad b(a + 1) = 4", explanation: "Two polynomials agree for all \\(x\\) iff their coefficients agree." }, { stepNumber: 4, description: "Solve for \\(a\\) using the positivity condition.", workingLatex: "a = \\pm 3; \\;a > 0 \\Rightarrow a = 3", explanation: "Reject the negative root because \\(a > 0\\) is given." }, { stepNumber: 5, description: "Back-substitute for \\(b\\).", workingLatex: "b(3 + 1) = 4 \\Rightarrow 4b = 4 \\Rightarrow b = 1", explanation: "" } ], finalAnswer: "\\( a = 3,\\; b = 1 \\)." } },
  { id: "y2fg3-020", topicRef: "y2fg3", topicTitle: "Composite Functions 08", difficulty: "Foundation", questionText: "If \\( f(x) = x^2 \\), find \\( ff(x) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Unpack the notation \\(ff(x)\\).", workingLatex: "ff(x) = f(f(x))", explanation: "Two consecutive applications of \\(f\\): first \\(f(x)\\), then \\(f\\) of that result." }, { stepNumber: 2, description: "Substitute the inner application.", workingLatex: "f(f(x)) = f(x^2)", explanation: "Replace the inner \\(f(x)\\) with its definition \\(x^2\\)." }, { stepNumber: 3, description: "Apply \\(f\\) (square) to \\(x^2\\).", workingLatex: "f(x^2) = (x^2)^2 = x^4", explanation: "Use the power rule \\((x^a)^b = x^{ab}\\): here \\((x^2)^2 = x^{2 \\cdot 2} = x^4\\)." } ], finalAnswer: "\\( ff(x) = x^4 \\)." } },
  { id: "y2fg3-021", topicRef: "y2fg3", topicTitle: "Composite Functions 32", difficulty: "Standard", questionText: "\\( f(x) = (x + 1)^2 \\) and \\( g(x) = 3x \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 16 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "quadratic"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = f(3x) = (3x + 1)^2", explanation: "Substitute \\(g(x) = 3x\\) into \\(f\\)." }, { stepNumber: 2, description: "Set equal to 16.", workingLatex: "(3x + 1)^2 = 16", explanation: "" }, { stepNumber: 3, description: "Take square roots.", workingLatex: "3x + 1 = \\pm 4", explanation: "Both signs solve the squared equation." }, { stepNumber: 4, description: "Solve each branch.", workingLatex: "+4:\\; 3x = 3 \\Rightarrow x = 1;\\quad -4:\\; 3x = -5 \\Rightarrow x = -\\tfrac{5}{3}", explanation: "" } ], finalAnswer: "\\( x = 1 \\) or \\( x = -\\tfrac{5}{3} \\)." } },
  { id: "y2fg3-022", topicRef: "y2fg3", topicTitle: "Composite Functions 33", difficulty: "Standard", questionText: "\\( f(x) = \\sqrt{x + 2} \\) \\((x \\ge -2)\\) and \\( g(x) = x^2 - 1 \\), \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 3 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "square root"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(x^2 - 1) = \\sqrt{(x^2 - 1) + 2}", explanation: "Apply \\(g\\) first, then take the square root \\(f\\)." }, { stepNumber: 2, description: "Simplify the radicand.", workingLatex: "\\sqrt{x^2 + 1}", explanation: "Combine constants \\(-1 + 2 = 1\\)." }, { stepNumber: 3, description: "Note the composite's domain.", workingLatex: "x^2 + 1 \\ge 1 > 0 \\text{ for all } x \\in \\mathbb R", explanation: "The inner expression is always positive, so the composite is defined everywhere — no restriction needed." }, { stepNumber: 4, description: "Set equal to 3 and square both sides.", workingLatex: "\\sqrt{x^2 + 1} = 3 \\Rightarrow x^2 + 1 = 9", explanation: "Squaring is valid since both sides are non-negative — no extraneous solutions introduced." }, { stepNumber: 5, description: "Solve for \\(x\\).", workingLatex: "x^2 = 8 \\Rightarrow x = \\pm \\sqrt{8} = \\pm 2\\sqrt{2}", explanation: "Simplify \\(\\sqrt{8} = \\sqrt{4 \\cdot 2} = 2\\sqrt{2}\\). Both signs are valid." } ], finalAnswer: "\\( x = \\pm 2\\sqrt{2} \\)." } },
  { id: "y2fg3-023", topicRef: "y2fg3", topicTitle: "Composite Functions 34", difficulty: "Challenge", questionText: "\\( f : x \\mapsto x^2 + b \\) and \\( g : x \\mapsto b - 3x \\), both with \\(x \\in \\mathbb R\\) (\\(b\\) is a constant). Given that \\( gf(2) = -8 \\), find the value of \\( b \\) and hence the value of \\( fg(2) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "parameter"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate \\( f(2) \\) in terms of \\(b\\).", workingLatex: "f(2) = 2^2 + b = 4 + b", explanation: "" }, { stepNumber: 2, description: "Substitute into \\(g\\) to form \\( gf(2) \\).", workingLatex: "gf(2) = g(4 + b) = b - 3(4 + b) = b - 12 - 3b = -2b - 12", explanation: "Apply \\(g\\) to the output of \\(f\\)." }, { stepNumber: 3, description: "Equate to \\(-8\\) and solve for \\(b\\).", workingLatex: "-2b - 12 = -8 \\Rightarrow -2b = 4 \\Rightarrow b = -2", explanation: "" }, { stepNumber: 4, description: "Compute \\( g(2) \\) using \\(b = -2\\).", workingLatex: "g(2) = -2 - 3(2) = -8", explanation: "" }, { stepNumber: 5, description: "Form \\( fg(2) \\) and evaluate.", workingLatex: "fg(2) = f(-8) = (-8)^2 + (-2) = 64 - 2 = 62", explanation: "Substitute \\(g(2) = -8\\) into \\(f\\) with \\(b = -2\\)." } ], finalAnswer: "\\( b = -2 \\); \\( fg(2) = 62 \\)." } },
  { id: "y2fg3-024", topicRef: "y2fg3", topicTitle: "Composite Functions 09", difficulty: "Foundation", questionText: "\\( f(x) = 2x \\) and \\( g(x) = x + 7 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 20 \\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(x + 7) = 2(x + 7)", explanation: "Apply \\(g\\) first (right-to-left), then \\(f\\) doubles the result." }, { stepNumber: 2, description: "Expand.", workingLatex: "2(x + 7) = 2x + 14", explanation: "Distribute the 2 through the bracket." }, { stepNumber: 3, description: "Set equal to 20 and solve.", workingLatex: "2x + 14 = 20 \\Rightarrow 2x = 6 \\Rightarrow x = 3", explanation: "Subtract 14, then divide by 2. Check: \\(g(3) = 10\\), \\(f(10) = 20\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 3 \\)." } },
  { id: "y2fg3-025", topicRef: "y2fg3", topicTitle: "Composite Functions 10", difficulty: "Foundation", questionText: "\\( f(x) = x - 4 \\) and \\( g(x) = 5x \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( gf(x) = 25 \\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(f\\) into \\(g\\).", workingLatex: "gf(x) = g(x - 4) = 5(x - 4)", explanation: "Apply \\(f\\) first to get \\(x - 4\\); then \\(g\\) multiplies by 5." }, { stepNumber: 2, description: "Expand.", workingLatex: "5(x - 4) = 5x - 20", explanation: "Distribute the 5 through the bracket." }, { stepNumber: 3, description: "Set equal to 25 and solve.", workingLatex: "5x - 20 = 25 \\Rightarrow 5x = 45 \\Rightarrow x = 9", explanation: "Add 20, then divide by 5. Check: \\(f(9) = 5\\), \\(g(5) = 25\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 9 \\)." } },
  { id: "y2fg3-026", topicRef: "y2fg3", topicTitle: "Composite Functions 11", difficulty: "Foundation", questionText: "\\( f(x) = x^2 \\) and \\( g(x) = 2x \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 36 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g(x) = 2x\\) into \\(f\\).", workingLatex: "fg(x) = f(2x) = (2x)^2", explanation: "Apply \\(g\\) first to get \\(2x\\); then \\(f\\) squares the result. Square the entire \\(2x\\), not just the \\(x\\)." }, { stepNumber: 2, description: "Expand the square.", workingLatex: "(2x)^2 = 4x^2", explanation: "Using \\((ab)^2 = a^2 b^2\\): \\((2x)^2 = 2^2 \\cdot x^2 = 4x^2\\)." }, { stepNumber: 3, description: "Set the composite equal to 36.", workingLatex: "4x^2 = 36", explanation: "" }, { stepNumber: 4, description: "Isolate \\(x^2\\).", workingLatex: "x^2 = 9", explanation: "Divide both sides by 4." }, { stepNumber: 5, description: "Take square roots.", workingLatex: "x = \\pm 3", explanation: "Both signs satisfy \\(x^2 = 9\\). Check: \\(g(\\pm 3) = \\pm 6\\); \\(f(\\pm 6) = 36\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = \\pm 3 \\)." } },
  { id: "y2fg3-027", topicRef: "y2fg3", topicTitle: "Composite Functions 35", difficulty: "Challenge", questionText: "\\( f(x) = 2x + 1 \\) and \\( g(x) = ax - 3 \\), both with \\(x \\in \\mathbb R\\) (\\(a\\) is a constant). Given that \\( fg(x) = gf(x) \\) for all real \\(x\\), find the value of \\( a \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "parameter"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\( fg(x) \\).", workingLatex: "fg(x) = f(ax - 3) = 2(ax - 3) + 1 = 2ax - 5", explanation: "Substitute \\(g\\) into \\(f\\) and simplify." }, { stepNumber: 2, description: "Form \\( gf(x) \\).", workingLatex: "gf(x) = g(2x + 1) = a(2x + 1) - 3 = 2ax + a - 3", explanation: "" }, { stepNumber: 3, description: "Equate for all \\(x\\).", workingLatex: "2ax - 5 = 2ax + a - 3", explanation: "Two linear polynomials are equal for all \\(x\\) iff their coefficients match. The \\(x\\)-coefficients (\\(2a\\)) already match, so the constants must agree." }, { stepNumber: 4, description: "Compare constants and solve.", workingLatex: "-5 = a - 3 \\Rightarrow a = -2", explanation: "" } ], finalAnswer: "\\( a = -2 \\)." } },
  { id: "y2fg3-028", topicRef: "y2fg3", topicTitle: "Composite Functions 36", difficulty: "Challenge", questionText: "\\( f(x) = ax + 1 \\) and \\( g(x) = bx + 2 \\), both with \\(x \\in \\mathbb R\\) (\\(a, b\\) constants). Given \\( fg(1) = 9 \\) and \\( gf(1) = 8 \\), find all possible pairs \\((a, b)\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "parameter"], workedSolution: { steps: [ { stepNumber: 1, description: "Translate \\(fg(1) = 9\\) into a condition on \\(a, b\\).", workingLatex: "g(1) = b + 2,\\;\\; fg(1) = a(b + 2) + 1 = 9 \\Rightarrow ab + 2a = 8 \\quad (\\star)", explanation: "Apply \\(g\\) at \\(x = 1\\), then feed into \\(f\\); expand the \\(a(b + 2)\\) bracket to make the system easy to subtract." }, { stepNumber: 2, description: "Translate \\(gf(1) = 8\\) similarly.", workingLatex: "f(1) = a + 1,\\;\\; gf(1) = b(a + 1) + 2 = 8 \\Rightarrow ab + b = 6 \\quad (\\star\\star)", explanation: "Same pattern; expand the bracket. Both equations now share the term \\(ab\\), which is what we'll exploit next." }, { stepNumber: 3, description: "Subtract \\((\\star\\star)\\) from \\((\\star)\\) to eliminate \\(ab\\).", workingLatex: "(ab + 2a) - (ab + b) = 8 - 6 \\Rightarrow 2a - b = 2 \\Rightarrow b = 2a - 2", explanation: "Cancelling the common \\(ab\\) collapses the system to a single linear relation between \\(a\\) and \\(b\\) — the natural way to extract a quadratic in one unknown without guessing." }, { stepNumber: 4, description: "Substitute \\(b = 2a - 2\\) back into \\((\\star)\\).", workingLatex: "a(2a - 2) + 2a = 8 \\Rightarrow 2a^2 - 2a + 2a = 8 \\Rightarrow 2a^2 = 8 \\Rightarrow a^2 = 4", explanation: "The linear terms in \\(a\\) cancel cleanly, leaving a pure quadratic. The two roots are \\(a = 2\\) and \\(a = -2\\) — both real, so both must be considered." }, { stepNumber: 5, description: "Read off the two corresponding \\(b\\)-values.", workingLatex: "a = 2 \\Rightarrow b = 2;\\quad a = -2 \\Rightarrow b = -6", explanation: "Use \\(b = 2a - 2\\) on each root of the quadratic." }, { stepNumber: 6, description: "Verify both pairs in the original equations.", workingLatex: "\\begin{aligned} (2, 2):&\\;\\; fg(1) = 2(2 + 2) + 1 = 9,\\; gf(1) = 2(2 + 1) + 2 = 8\\;\\checkmark\\\\ (-2, -6):&\\;\\; fg(1) = -2(-6 + 2) + 1 = 9,\\; gf(1) = -6(-2 + 1) + 2 = 8\\;\\checkmark \\end{aligned}", explanation: "Always sanity-check both roots. Both pairs satisfy the original constraints, so both are valid; if the question had imposed \\(a > 0\\), only \\((2, 2)\\) would qualify." } ], finalAnswer: "\\( (a, b) = (2, 2) \\) or \\( (a, b) = (-2, -6) \\)." } },
  // ── Solving fg(x) = k ────
  { id: "y2fg3-029", topicRef: "y2fg3", topicTitle: "Composite Functions 37", difficulty: "Challenge", questionText: "\\( f(x) = e^x \\) and \\( g(x) = x^2 - 5 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 1 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = e^{x^2 - 5}", explanation: "Substitute \\(g\\) into the exponent of \\(f\\)." }, { stepNumber: 2, description: "Set equal to 1.", workingLatex: "e^{x^2 - 5} = 1", explanation: "" }, { stepNumber: 3, description: "Take logs (or use \\(e^a = 1 \\iff a = 0\\)).", workingLatex: "x^2 - 5 = 0", explanation: "\\(e^a = 1\\) iff \\(a = 0\\) (exponential is one-to-one with \\(e^0 = 1\\))." }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "x^2 = 5 \\Rightarrow x = \\pm \\sqrt{5}", explanation: "" } ], finalAnswer: "\\( x = \\pm \\sqrt{5} \\)." } },
  { id: "y2fg3-030", topicRef: "y2fg3", topicTitle: "Composite Functions 38", difficulty: "Challenge", questionText: "\\( f(x) = x + 1 \\) and \\( g(x) = x^2 - 3 \\), both with \\(x \\in \\mathbb R\\). Find all values of \\(x\\) for which \\( fg(x) = gf(x) \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(fg(x)\\).", workingLatex: "fg(x) = (x^2 - 3) + 1 = x^2 - 2", explanation: "Apply \\(g\\) first, then \\(f\\) adds 1." }, { stepNumber: 2, description: "Form \\(gf(x)\\).", workingLatex: "gf(x) = (x + 1)^2 - 3 = x^2 + 2x - 2", explanation: "Apply \\(f\\) first, then square and subtract 3." }, { stepNumber: 3, description: "Equate and simplify.", workingLatex: "x^2 - 2 = x^2 + 2x - 2 \\Rightarrow 0 = 2x", explanation: "The \\(x^2\\) and constant terms cancel — what remains is a linear equation." }, { stepNumber: 4, description: "Solve.", workingLatex: "x = 0", explanation: "Verify: \\(fg(0) = -3 + 1 = -2\\) and \\(gf(0) = 1 - 3 = -2\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 0 \\) is the only value." } },
  { id: "y2fg3-031", topicRef: "y2fg3", topicTitle: "Composite Functions 39", difficulty: "Challenge", questionText: "\\( f(x) = x^2 + 1 \\) with \\(x \\in \\mathbb R\\). Solve \\( ff(x) = 5 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "quadratic"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(ff(x)\\).", workingLatex: "ff(x) = (x^2 + 1)^2 + 1", explanation: "Substitute \\(f(x) = x^2 + 1\\) back into \\(f\\)." }, { stepNumber: 2, description: "Set equal to 5 and isolate the square.", workingLatex: "(x^2 + 1)^2 + 1 = 5 \\Rightarrow (x^2 + 1)^2 = 4", explanation: "Subtract 1." }, { stepNumber: 3, description: "Take square roots.", workingLatex: "x^2 + 1 = \\pm 2", explanation: "Algebraically both branches arise; we must check feasibility." }, { stepNumber: 4, description: "Discard the infeasible branch.", workingLatex: "x^2 + 1 = -2: \\text{ no real solution (since } x^2 + 1 \\ge 1)", explanation: "The left side is always at least 1, so it cannot equal \\(-2\\)." }, { stepNumber: 5, description: "Solve the feasible branch.", workingLatex: "x^2 + 1 = 2 \\Rightarrow x^2 = 1 \\Rightarrow x = \\pm 1", explanation: "" } ], finalAnswer: "\\( x = \\pm 1 \\)." } },
  { id: "y2fg3-032", topicRef: "y2fg3", topicTitle: "Composite Functions 40", difficulty: "Challenge", questionText: "\\( f(x) = \\ln x \\) \\((x > 0)\\) and \\( g(x) = e^x - k \\), where \\(k\\) is a constant. Given that \\( fg(1) = 0 \\), find \\(k\\), and hence solve \\( fg(x) = \\ln 5 \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "parameter", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the condition \\(fg(1) = 0\\) to find \\(k\\).", workingLatex: "g(1) = e - k,\\;\\; fg(1) = \\ln(e - k) = 0", explanation: "Apply \\(g\\) first, then \\(f\\)." }, { stepNumber: 2, description: "Solve for \\(k\\).", workingLatex: "\\ln(e - k) = 0 \\Rightarrow e - k = 1 \\Rightarrow k = e - 1", explanation: "\\(\\ln y = 0 \\iff y = 1\\)." }, { stepNumber: 3, description: "Write down \\(g\\) and form the general composite.", workingLatex: "g(x) = e^x - (e - 1);\\;\\; fg(x) = \\ln(e^x - e + 1)", explanation: "Domain: \\(e^x - e + 1 > 0\\). At \\(x = 1\\) this gives 1, and the expression grows with \\(x\\), so it's positive for all \\(x \\ge 1\\) at least; in fact for all \\(x \\in \\mathbb R\\) since \\(e^x > 0\\) and \\(1 > e - 1\\) is false but for \\(x \\to -\\infty\\), \\(e^x \\to 0\\), so the limit is \\(1 - e + 1 = 2 - e < 0\\). So domain is where \\(e^x > e - 1\\), i.e. \\(x > \\ln(e - 1)\\)." }, { stepNumber: 4, description: "Set the composite equal to \\(\\ln 5\\).", workingLatex: "\\ln(e^x - e + 1) = \\ln 5 \\Rightarrow e^x - e + 1 = 5", explanation: "\\(\\ln\\) is one-to-one, so equating arguments is valid." }, { stepNumber: 5, description: "Solve for \\(x\\).", workingLatex: "e^x = 4 + e \\Rightarrow x = \\ln(4 + e)", explanation: "Take logs; the right side is positive so this is well-defined." } ], finalAnswer: "\\( k = e - 1 \\); \\( x = \\ln(4 + e) \\)." } },
  { id: "y2fg3-033", topicRef: "y2fg3", topicTitle: "Composite Functions 41", difficulty: "Challenge", questionText: "\\( f(x) = ax + b \\) and \\( g(x) = x + c \\), where \\(a, b, c\\) are constants with \\(c \\ne 0\\). Find all values of \\(a\\) such that \\( fg(x) = gf(x) \\) holds for every real \\(x\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(fg(x)\\).", workingLatex: "fg(x) = a(x + c) + b = ax + ac + b", explanation: "Apply \\(g\\) first, then \\(f\\)." }, { stepNumber: 2, description: "Form \\(gf(x)\\).", workingLatex: "gf(x) = (ax + b) + c = ax + b + c", explanation: "Apply \\(f\\) first, then \\(g\\) shifts by \\(c\\)." }, { stepNumber: 3, description: "Match coefficients.", workingLatex: "ax + (ac + b) = ax + (b + c) \\Rightarrow ac = c", explanation: "The \\(x\\)-coefficients already agree (both \\(a\\)); the constants must too." }, { stepNumber: 4, description: "Factor and use \\(c \\ne 0\\).", workingLatex: "c(a - 1) = 0;\\; c \\ne 0 \\Rightarrow a = 1", explanation: "Dividing by the non-zero \\(c\\) forces \\(a = 1\\)." } ], finalAnswer: "\\( a = 1 \\) is the only value (the case \\(c = 0\\) is excluded)." } },
  { id: "y2fg3-034", topicRef: "y2fg3", topicTitle: "Composite Functions 42", difficulty: "Challenge", questionText: "\\( f(x) = \\sqrt{x + a} \\), with \\(a\\) a constant, and \\( g(x) = x^2 - 1 \\) for \\(x \\ge 0\\). Given that \\( fg(0) = 1 \\), find \\(a\\), and state the largest possible domain of \\( fg \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "domain", "square root"], workedSolution: { steps: [ { stepNumber: 1, description: "Use \\(fg(0) = 1\\) to set up an equation for \\(a\\).", workingLatex: "g(0) = -1,\\;\\; fg(0) = f(-1) = \\sqrt{-1 + a} = 1", explanation: "Apply \\(g\\) at \\(x = 0\\) first, then feed the result into \\(f\\)." }, { stepNumber: 2, description: "Square and solve for \\(a\\).", workingLatex: "-1 + a = 1 \\Rightarrow a = 2", explanation: "Squaring is valid since both sides are non-negative." }, { stepNumber: 3, description: "Write down the composite explicitly.", workingLatex: "fg(x) = \\sqrt{(x^2 - 1) + 2} = \\sqrt{x^2 + 1}", explanation: "Simplify the radicand." }, { stepNumber: 4, description: "Find the largest domain.", workingLatex: "x^2 + 1 \\ge 1 > 0 \\text{ for all } x \\in \\mathbb R", explanation: "The inner expression is always positive, so the square root is defined everywhere — no restriction from \\(f\\)." }, { stepNumber: 5, description: "Apply the restriction inherited from \\(g\\).", workingLatex: "\\text{Domain of } fg: \\; x \\ge 0", explanation: "Since \\(g\\) is only defined for \\(x \\ge 0\\), the composite inherits this restriction." } ], finalAnswer: "\\( a = 2 \\); domain of \\( fg \\) is \\( x \\ge 0 \\)." } },
  { id: "y2fg3-035", topicRef: "y2fg3", topicTitle: "Composite Functions 43", difficulty: "Challenge", questionText: "\\( f(x) = \\dfrac{1}{x - 1} \\) \\((x \\ne 1)\\) and \\( g(x) = 2x + a \\), where \\(a\\) is a constant. Given \\( fg(0) = \\tfrac{1}{3} \\), find \\(a\\), and hence solve \\( fg(x) = -1 \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "solve", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Use \\(fg(0) = \\tfrac{1}{3}\\).", workingLatex: "g(0) = a,\\;\\; fg(0) = \\tfrac{1}{a - 1} = \\tfrac{1}{3}", explanation: "Apply \\(g\\) at \\(x = 0\\) first, then feed into \\(f\\)." }, { stepNumber: 2, description: "Solve for \\(a\\).", workingLatex: "a - 1 = 3 \\Rightarrow a = 4", explanation: "Reciprocate (or cross-multiply)." }, { stepNumber: 3, description: "Write the general composite.", workingLatex: "g(x) = 2x + 4,\\;\\; fg(x) = \\tfrac{1}{(2x + 4) - 1} = \\tfrac{1}{2x + 3}", explanation: "Simplify the denominator. Domain restriction: \\(2x + 3 \\ne 0 \\Rightarrow x \\ne -\\tfrac{3}{2}\\)." }, { stepNumber: 4, description: "Set equal to \\(-1\\) and solve.", workingLatex: "\\tfrac{1}{2x + 3} = -1 \\Rightarrow 2x + 3 = -1 \\Rightarrow x = -2", explanation: "Reciprocate. Check \\(x = -2 \\ne -\\tfrac{3}{2}\\), so valid." } ], finalAnswer: "\\( a = 4 \\); \\( x = -2 \\)." } },
  // ── Specific values fg(a), gf(a) ────
  { id: "y2fg3-036", topicRef: "y2fg3", topicTitle: "Composite Functions 12", difficulty: "Foundation", questionText: "\\( f(x) = 3x + 1 \\) and \\( g(x) = x - 2 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( gf(x) = 5 \\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(f\\) into \\(g\\).", workingLatex: "gf(x) = g(3x + 1) = (3x + 1) - 2", explanation: "Apply \\(f\\) first; \\(g\\) then subtracts 2." }, { stepNumber: 2, description: "Simplify the composite.", workingLatex: "(3x + 1) - 2 = 3x - 1", explanation: "Combine constants." }, { stepNumber: 3, description: "Set equal to 5 and solve.", workingLatex: "3x - 1 = 5 \\Rightarrow 3x = 6 \\Rightarrow x = 2", explanation: "Add 1, then divide by 3. Check: \\(f(2) = 7\\), \\(g(7) = 5\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 2 \\)." } },
  { id: "y2fg3-037", topicRef: "y2fg3", topicTitle: "Composite Functions 13", difficulty: "Foundation", questionText: "\\( f(x) = x - 1 \\) and \\( g(x) = 2x \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = 7 \\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(2x) = (2x) - 1 = 2x - 1", explanation: "Apply \\(g\\) first to get \\(2x\\); \\(f\\) then subtracts 1." }, { stepNumber: 2, description: "Set the composite equal to 7.", workingLatex: "2x - 1 = 7", explanation: "" }, { stepNumber: 3, description: "Solve for \\(x\\).", workingLatex: "2x = 8 \\Rightarrow x = 4", explanation: "Add 1 to both sides, then divide by 2. Check: \\(g(4) = 8\\), \\(f(8) = 7\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 4 \\)." } },
  { id: "y2fg3-038", topicRef: "y2fg3", topicTitle: "Composite Functions 14", difficulty: "Foundation", questionText: "\\( f(x) = x + 2 \\) and \\( g(x) = x^2 \\), both with \\(x \\in \\mathbb R\\). Solve the equation \\( gf(x) = 16 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(f\\) into \\(g\\).", workingLatex: "gf(x) = g(x + 2) = (x + 2)^2", explanation: "Apply \\(f\\) first to get \\(x + 2\\); \\(g\\) then squares this expression — keep the bracket." }, { stepNumber: 2, description: "Set the composite equal to 16.", workingLatex: "(x + 2)^2 = 16", explanation: "" }, { stepNumber: 3, description: "Take square roots of both sides.", workingLatex: "x + 2 = \\pm 4", explanation: "Both signs satisfy the squared equation, so both branches must be considered." }, { stepNumber: 4, description: "Solve each branch.", workingLatex: "+4:\\; x = 2;\\quad -4:\\; x = -6", explanation: "Subtract 2 in each case. Check: \\(f(2) = 4 \\Rightarrow g(4) = 16\\) \\(\\checkmark\\); \\(f(-6) = -4 \\Rightarrow g(-4) = 16\\) \\(\\checkmark\\)." } ], finalAnswer: "\\( x = 2 \\) or \\( x = -6 \\)." } },
  { id: "y2fg3-039", topicRef: "y2fg3", topicTitle: "Composite Functions 15", difficulty: "Foundation", questionText: "Evaluate \\( ff(2) \\) where \\( f(x) = 3x - 1 \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Unpack the notation.", workingLatex: "ff(2) = f(f(2))", explanation: "Two applications of \\(f\\): first \\(f(2)\\), then \\(f\\) of that result." }, { stepNumber: 2, description: "Apply \\(f\\) to 2.", workingLatex: "f(2) = 3(2) - 1 = 5", explanation: "Substitute \\(x = 2\\) into \\(3x - 1\\)." }, { stepNumber: 3, description: "Apply \\(f\\) again to the result.", workingLatex: "f(5) = 3(5) - 1 = 14", explanation: "Now feed \\(5\\) into \\(f\\)." }, { stepNumber: 4, description: "Combine.", workingLatex: "ff(2) = f(f(2)) = f(5) = 14", explanation: "Chain the two evaluations together." } ], finalAnswer: "\\( ff(2) = 14 \\)." } },
  { id: "y2fg3-040", topicRef: "y2fg3", topicTitle: "Composite Functions 44", difficulty: "Challenge", questionText: "\\( f(x) = ax + b \\) and \\( g(x) = x^2 \\), both with \\(x \\in \\mathbb R\\) (\\(a, b\\) constants). Given that \\( fg(2) = 7 \\) and \\( fg(-1) = 1 \\), find the values of \\(a\\) and \\(b\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Translate \\(fg(2) = 7\\) into an equation.", workingLatex: "g(2) = 4,\\;\\; fg(2) = 4a + b = 7 \\quad (\\star)", explanation: "Apply \\(g\\) first; then \\(f(4) = 4a + b\\)." }, { stepNumber: 2, description: "Translate \\(fg(-1) = 1\\) similarly.", workingLatex: "g(-1) = 1,\\;\\; fg(-1) = a + b = 1 \\quad (\\star\\star)", explanation: "\\(g(-1) = (-1)^2 = 1\\); then \\(f(1) = a + b\\)." }, { stepNumber: 3, description: "Subtract to eliminate \\(b\\).", workingLatex: "(4a + b) - (a + b) = 7 - 1 \\Rightarrow 3a = 6 \\Rightarrow a = 2", explanation: "" }, { stepNumber: 4, description: "Back-substitute for \\(b\\).", workingLatex: "2 + b = 1 \\Rightarrow b = -1", explanation: "" } ], finalAnswer: "\\( a = 2,\\; b = -1 \\)." } },
  // ── Three-function composition ────
  { id: "y2fg3-041", topicRef: "y2fg3", topicTitle: "Composite Functions 45", difficulty: "Challenge", questionText: "\\( f(x) = \\dfrac{1}{x} \\) \\((x \\ne 0)\\) and \\( g(x) = x^2 - 1 \\), \\(x \\in \\mathbb R\\). Find the largest possible domain and the range of \\( fg(x) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "domain", "range", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite.", workingLatex: "fg(x) = \\tfrac{1}{x^2 - 1}", explanation: "Substitute \\(g\\) into \\(f\\)." }, { stepNumber: 2, description: "Find the domain.", workingLatex: "x^2 - 1 \\ne 0 \\Rightarrow x \\ne \\pm 1", explanation: "Composite is undefined where the inner expression hits a zero of the denominator." }, { stepNumber: 3, description: "Analyse the range on \\(|x| > 1\\).", workingLatex: "|x| > 1 \\Rightarrow x^2 - 1 > 0;\\; x^2 - 1 \\in (0, \\infty) \\Rightarrow \\tfrac{1}{x^2 - 1} \\in (0, \\infty)", explanation: "On either outer branch, the denominator is positive and ranges over all positive reals (close to 0 as \\(|x| \\to 1^+\\), large as \\(|x| \\to \\infty\\))." }, { stepNumber: 4, description: "Analyse the range on \\(|x| < 1\\).", workingLatex: "-1 < x < 1 \\Rightarrow x^2 - 1 \\in [-1, 0)", explanation: "Inner expression negative, reaching its minimum \\(-1\\) at \\(x = 0\\) and approaching \\(0^-\\) as \\(|x| \\to 1^-\\)." }, { stepNumber: 5, description: "Reciprocate to find the composite's values on this region.", workingLatex: "\\tfrac{1}{x^2 - 1} \\in (-\\infty, -1]", explanation: "Reciprocal of \\([-1, 0)\\) is \\((-\\infty, -1]\\); upper bound \\(-1\\) attained at \\(x = 0\\), infimum \\(-\\infty\\) approached as \\(|x| \\to 1^-\\)." }, { stepNumber: 6, description: "Combine for the full range.", workingLatex: "\\text{Range: } (-\\infty, -1] \\cup (0, \\infty)", explanation: "Union of the two sub-ranges from the two regions of the domain." } ], finalAnswer: "Domain: \\( x \\ne \\pm 1 \\); range: \\( y \\le -1 \\) or \\( y > 0 \\)." } },
  { id: "y2fg3-042", topicRef: "y2fg3", topicTitle: "Composite Functions 46", difficulty: "Challenge", questionText: "\\( f(x) = e^x \\), \\(x \\in \\mathbb R\\), and \\( g(x) = ax \\), where \\(a\\) is a constant. Given that \\( fg(2) = e^6 \\), find \\(a\\), and hence solve \\( gf(x) = 12 \\). Give your answer in exact form.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "solve", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(fg(x)\\).", workingLatex: "fg(x) = e^{ax}", explanation: "Substitute \\(g\\) into the exponent of \\(f\\)." }, { stepNumber: 2, description: "Use the given value at \\(x = 2\\).", workingLatex: "e^{2a} = e^6 \\Rightarrow 2a = 6 \\Rightarrow a = 3", explanation: "Equate exponents (exponential is one-to-one)." }, { stepNumber: 3, description: "Form \\(gf(x)\\) with \\(a = 3\\).", workingLatex: "gf(x) = 3 e^x", explanation: "Apply \\(f\\) first to get \\(e^x\\); then \\(g\\) multiplies by 3." }, { stepNumber: 4, description: "Set equal to 12.", workingLatex: "3 e^x = 12 \\Rightarrow e^x = 4", explanation: "Divide by 3." }, { stepNumber: 5, description: "Take logs.", workingLatex: "x = \\ln 4 = 2 \\ln 2", explanation: "Use \\(\\ln 4 = \\ln(2^2) = 2 \\ln 2\\) for a cleaner exact form." } ], finalAnswer: "\\( a = 3 \\); \\( x = \\ln 4 = 2 \\ln 2 \\)." } },
  { id: "y2fg3-043", topicRef: "y2fg3", topicTitle: "Composite Functions 47", difficulty: "Challenge", questionText: "\\( f(x) = \\sqrt{x} \\) \\((x \\ge 0)\\) and \\( g(x) = x^2 + a \\), where \\(a\\) is a constant. Given \\( fg(2) = 3 \\), find \\(a\\), and state the range of \\( fg \\) on \\(x \\in \\mathbb R\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "range", "square root"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the condition to find \\(a\\).", workingLatex: "g(2) = 4 + a,\\;\\; fg(2) = \\sqrt{4 + a} = 3", explanation: "" }, { stepNumber: 2, description: "Square and solve.", workingLatex: "4 + a = 9 \\Rightarrow a = 5", explanation: "Squaring is valid since both sides are non-negative." }, { stepNumber: 3, description: "Form the general composite.", workingLatex: "g(x) = x^2 + 5,\\;\\; fg(x) = \\sqrt{x^2 + 5}", explanation: "Inner expression is always \\(\\ge 5 > 0\\), so the composite is defined for all real \\(x\\)." }, { stepNumber: 4, description: "Find the range — minimum of the inside.", workingLatex: "x^2 + 5 \\ge 5,\\; \\text{equality at } x = 0", explanation: "\\(x^2 \\ge 0\\) gives the lower bound." }, { stepNumber: 5, description: "Apply the square root.", workingLatex: "fg(x) \\ge \\sqrt{5};\\; fg(x) \\to \\infty \\text{ as } |x| \\to \\infty", explanation: "Square root is increasing on positive reals; minimum value \\(\\sqrt{5}\\) attained, unbounded above." } ], finalAnswer: "\\( a = 5 \\); range \\([\\sqrt{5}, \\infty)\\)." } },
  // ── Finding component functions ────
  { id: "y2fg3-044", topicRef: "y2fg3", topicTitle: "Composite Functions 64", difficulty: "Challenge", questionText: "\\( f(x) = \\sqrt{x + 3} \\) \\((x \\ge -3)\\) and \\( g(x) = x^2 - 2 \\) \\((x \\ge 0)\\). Solve the equation \\( fg(x) = 4 \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "domain"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = \\sqrt{(x^2 - 2) + 3} = \\sqrt{x^2 + 1}", explanation: "Substitute \\(g\\) into \\(f\\) and simplify the radicand." }, { stepNumber: 2, description: "Note the composite domain.", workingLatex: "x \\ge 0", explanation: "Inherited from \\(g\\); the inner square root \\(\\sqrt{x^2 + 1}\\) is always defined since \\(x^2 + 1 \\ge 1\\)." }, { stepNumber: 3, description: "Set equal to 4 and square.", workingLatex: "\\sqrt{x^2 + 1} = 4 \\Rightarrow x^2 + 1 = 16", explanation: "Squaring is valid since both sides are non-negative." }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "x^2 = 15 \\Rightarrow x = \\sqrt{15}", explanation: "Reject \\(x = -\\sqrt{15}\\) because the domain requires \\(x \\ge 0\\)." } ], finalAnswer: "\\( x = \\sqrt{15} \\)." } },
  { id: "y2fg3-045", topicRef: "y2fg3", topicTitle: "Composite Functions 65", difficulty: "Challenge", questionText: "\\( f(x) = \\ln x \\) \\((x > 0)\\) and \\( g(x) = x^2 \\) \\((x > 0)\\). Solve the equation \\( fg(x) = 6 \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = \\ln(x^2)", explanation: "Composite domain is \\(x > 0\\) (from \\(g\\); and \\(x^2 > 0\\) automatically there)." }, { stepNumber: 2, description: "Use a log law to simplify.", workingLatex: "\\ln(x^2) = 2\\ln x", explanation: "\\(\\ln(a^b) = b \\ln a\\). Valid since \\(x > 0\\)." }, { stepNumber: 3, description: "Set equal to 6 and solve.", workingLatex: "2 \\ln x = 6 \\Rightarrow \\ln x = 3", explanation: "Divide by 2." }, { stepNumber: 4, description: "Exponentiate.", workingLatex: "x = e^3", explanation: "Apply \\(e^{(\\cdot)}\\) to both sides. \\(e^3 > 0\\), inside the domain." } ], finalAnswer: "\\( x = e^3 \\)." } },
  { id: "y2fg3-046", topicRef: "y2fg3", topicTitle: "Composite Functions 66", difficulty: "Challenge", questionText: "\\( f(x) = \\dfrac{1}{x - 2} \\) \\((x \\ne 2)\\) and \\( g(x) = x + 5 \\), \\(x \\in \\mathbb R\\). Solve the equation \\( fg(x) = \\tfrac{1}{4} \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(x + 5) = \\tfrac{1}{(x + 5) - 2}", explanation: "Apply \\(g\\) first to get \\(x + 5\\); then place this expression as the denominator's argument in \\(f\\)." }, { stepNumber: 2, description: "Simplify the denominator.", workingLatex: "(x + 5) - 2 = x + 3 \\Rightarrow fg(x) = \\tfrac{1}{x + 3}", explanation: "Combine constants." }, { stepNumber: 3, description: "Identify the composite's domain.", workingLatex: "x + 5 \\ne 2 \\Leftrightarrow x \\ne -3", explanation: "\\(f\\) needs its denominator non-zero. Through \\(g\\), this excludes \\(x = -3\\) from the composite." }, { stepNumber: 4, description: "Set equal to \\(\\tfrac{1}{4}\\) and reciprocate.", workingLatex: "\\tfrac{1}{x + 3} = \\tfrac{1}{4} \\Rightarrow x + 3 = 4", explanation: "Equal reciprocals \\(\\Rightarrow\\) equal arguments. (Or cross-multiply: \\(4 = x + 3\\).)" }, { stepNumber: 5, description: "Solve.", workingLatex: "x = 1", explanation: "Valid since \\(1 \\ne -3\\). Check: \\(g(1) = 6\\); \\(f(6) = \\tfrac{1}{4}\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 1 \\)." } },
  // ── Non-commutativity examples ────
  { id: "y2fg3-047", topicRef: "y2fg3", topicTitle: "Composite Functions 48", difficulty: "Standard", questionText: "With \\( f(x) = 2x + 1 \\) and \\( g(x) = x^2 \\), show that \\( fg(x) \\ne gf(x) \\) as functions.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(fg(x)\\).", workingLatex: "fg(x) = f(x^2) = 2x^2 + 1", explanation: "Substitute \\(g\\) into \\(f\\)." }, { stepNumber: 2, description: "Form \\(gf(x)\\).", workingLatex: "gf(x) = g(2x + 1) = (2x + 1)^2 = 4x^2 + 4x + 1", explanation: "Substitute \\(f\\) into \\(g\\) and expand." }, { stepNumber: 3, description: "Compare via subtraction.", workingLatex: "gf(x) - fg(x) = (4x^2 + 4x + 1) - (2x^2 + 1) = 2x^2 + 4x = 2x(x + 2)", explanation: "Find where the two expressions agree by looking at where the difference is zero." }, { stepNumber: 4, description: "Identify the exceptional inputs.", workingLatex: "2x(x + 2) = 0 \\iff x = 0 \\text{ or } x = -2", explanation: "The two composites agree at exactly these two points; everywhere else they disagree." }, { stepNumber: 5, description: "Conclude.", workingLatex: "fg \\ne gf \\text{ as functions}", explanation: "Disagreement at a single (non-empty) set of inputs is enough to show the two functions are not equal — composition is not generally commutative." } ], finalAnswer: "\\( fg \\ne gf \\) — they agree only at \\(x = 0\\) and \\(x = -2\\); elsewhere \\(gf(x) - fg(x) = 2x(x+2) \\ne 0\\)." } },
  { id: "y2fg3-048", topicRef: "y2fg3", topicTitle: "Composite Functions 49", difficulty: "Standard", questionText: "If \\(f(x) = x + a\\) and \\(g(x) = x + b\\), show that \\(fg = gf\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\) to form \\(fg(x)\\).", workingLatex: "fg(x) = f(x + b) = (x + b) + a", explanation: "Apply \\(g\\) first to get \\(x + b\\); \\(f\\) then adds \\(a\\) to whatever it is given." }, { stepNumber: 2, description: "Collect.", workingLatex: "fg(x) = x + a + b", explanation: "Addition is associative, so we can drop the brackets." }, { stepNumber: 3, description: "Substitute \\(f\\) into \\(g\\) to form \\(gf(x)\\).", workingLatex: "gf(x) = g(x + a) = (x + a) + b = x + a + b", explanation: "Apply \\(f\\) first to get \\(x + a\\); \\(g\\) adds \\(b\\). Same final expression." }, { stepNumber: 4, description: "Conclude.", workingLatex: "fg(x) = x + a + b = gf(x) \\text{ for all } x", explanation: "Both composites produce the same function. The order of two pure shifts doesn't matter because addition of constants is commutative: \\(a + b = b + a\\)." } ], finalAnswer: "\\( fg(x) = gf(x) = x + a + b \\). \\(\\blacksquare\\)" } },
  // ── Domain of composite ────
  { id: "y2fg3-049", topicRef: "y2fg3", topicTitle: "Composite Functions 50", difficulty: "Challenge", questionText: "\\( f(x) = \\ln x \\) \\((x > 0)\\) and \\( g(x) = x - k \\), \\(x \\in \\mathbb R\\), where \\(k\\) is a constant. Given that the natural domain of \\( fg \\) is \\(x > 3\\), find \\(k\\), and then solve \\( fg(x) = \\ln 2 \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "domain", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the domain condition.", workingLatex: "fg(x) = \\ln(x - k) \\text{ requires } x - k > 0 \\Rightarrow x > k", explanation: "The argument of \\(\\ln\\) must be strictly positive." }, { stepNumber: 2, description: "Match to the given domain.", workingLatex: "x > k \\equiv x > 3 \\Rightarrow k = 3", explanation: "" }, { stepNumber: 3, description: "Write the composite explicitly.", workingLatex: "fg(x) = \\ln(x - 3)", explanation: "" }, { stepNumber: 4, description: "Set equal to \\(\\ln 2\\).", workingLatex: "\\ln(x - 3) = \\ln 2 \\Rightarrow x - 3 = 2", explanation: "\\(\\ln\\) is one-to-one, so equating arguments is valid." }, { stepNumber: 5, description: "Solve.", workingLatex: "x = 5", explanation: "Valid: \\(5 > 3\\), inside the domain." } ], finalAnswer: "\\( k = 3 \\); \\( x = 5 \\)." } },
  { id: "y2fg3-050", topicRef: "y2fg3", topicTitle: "Composite Functions 51", difficulty: "Challenge", questionText: "\\( f(x) = \\dfrac{1}{x} \\) \\((x \\ne 0)\\) and \\( g(x) = x + 1 \\), \\(x \\in \\mathbb R\\). Solve \\( fg(x) + gf(x) = 3 \\), giving your answer in exact form.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(fg(x)\\) and \\(gf(x)\\).", workingLatex: "fg(x) = \\tfrac{1}{x + 1};\\;\\; gf(x) = \\tfrac{1}{x} + 1 = \\tfrac{x + 1}{x}", explanation: "Compute each composite separately. Domain restrictions: \\(x \\ne 0\\) and \\(x \\ne -1\\)." }, { stepNumber: 2, description: "Sum and set equal to 3.", workingLatex: "\\tfrac{1}{x + 1} + \\tfrac{x + 1}{x} = 3", explanation: "" }, { stepNumber: 3, description: "Multiply through by \\(x(x + 1)\\).", workingLatex: "x + (x + 1)^2 = 3x(x + 1)", explanation: "Common denominator is \\(x(x + 1)\\)." }, { stepNumber: 4, description: "Expand both sides.", workingLatex: "x + x^2 + 2x + 1 = 3x^2 + 3x \\Rightarrow x^2 + 3x + 1 = 3x^2 + 3x", explanation: "" }, { stepNumber: 5, description: "Collect and simplify.", workingLatex: "1 = 2x^2 \\Rightarrow x^2 = \\tfrac{1}{2}", explanation: "The \\(x\\)-terms cancel cleanly." }, { stepNumber: 6, description: "Take square roots and check feasibility.", workingLatex: "x = \\pm \\tfrac{1}{\\sqrt{2}} = \\pm \\tfrac{\\sqrt{2}}{2}", explanation: "Both values are non-zero and \\(\\ne -1\\), so both are valid." } ], finalAnswer: "\\( x = \\pm \\tfrac{\\sqrt{2}}{2} \\)." } },
  { id: "y2fg3-051", topicRef: "y2fg3", topicTitle: "Composite Functions 67", difficulty: "Challenge", questionText: "\\( f : x \\mapsto \\sqrt{x} \\) \\((x \\ge 0)\\) and \\( g : x \\mapsto \\dfrac{1}{x - 1} \\) \\((x > 1)\\). Solve the equation \\( fg(x) = \\tfrac{1}{2} \\) and state the range of \\( fg(x) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite \\( fg(x) \\).", workingLatex: "fg(x) = \\sqrt{\\tfrac{1}{x - 1}} = \\tfrac{1}{\\sqrt{x - 1}}", explanation: "Substitute \\(g\\) into \\(f\\). The inner expression \\(\\tfrac{1}{x-1}\\) is positive on the domain \\(x > 1\\), so the square root is well-defined." }, { stepNumber: 2, description: "Set equal to \\(\\tfrac{1}{2}\\) and rearrange.", workingLatex: "\\tfrac{1}{\\sqrt{x - 1}} = \\tfrac{1}{2} \\Rightarrow \\sqrt{x - 1} = 2", explanation: "Reciprocate both sides." }, { stepNumber: 3, description: "Square and solve.", workingLatex: "x - 1 = 4 \\Rightarrow x = 5", explanation: "Valid since \\(5 > 1\\) (inside the domain)." }, { stepNumber: 4, description: "Track the range as \\(x \\to 1^+\\) and \\(x \\to \\infty\\).", workingLatex: "x \\to 1^+: \\tfrac{1}{x-1} \\to \\infty \\Rightarrow fg \\to \\infty;\\quad x \\to \\infty: \\tfrac{1}{x-1} \\to 0^+ \\Rightarrow fg \\to 0^+", explanation: "Track the limits at each boundary of the domain to find the range." }, { stepNumber: 5, description: "State the range.", workingLatex: "fg(x) > 0", explanation: "All positive values are achieved (the function is continuous and decreasing on \\(x > 1\\)); 0 is approached but never attained." } ], finalAnswer: "\\( x = 5 \\); range \\( fg(x) > 0 \\)." } },
  // ── More compositions ────
  { id: "y2fg3-052", topicRef: "y2fg3", topicTitle: "Composite Functions 16", difficulty: "Foundation", questionText: "For \\(f(x) = 3x\\) and \\(g(x) = 2x - 1\\), find \\(fg(x)\\) and \\(gf(x)\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\) to form \\(fg(x)\\).", workingLatex: "fg(x) = f(2x - 1) = 3(2x - 1)", explanation: "Apply \\(g\\) first (right-to-left); then \\(f\\) triples." }, { stepNumber: 2, description: "Expand.", workingLatex: "3(2x - 1) = 6x - 3", explanation: "Distribute the 3 through the bracket." }, { stepNumber: 3, description: "Substitute \\(f\\) into \\(g\\) to form \\(gf(x)\\).", workingLatex: "gf(x) = g(3x) = 2(3x) - 1 = 6x - 1", explanation: "Apply \\(f\\) first to get \\(3x\\); \\(g\\) doubles and subtracts 1." }, { stepNumber: 4, description: "Compare and note the asymmetry.", workingLatex: "fg(x) - gf(x) = (6x - 3) - (6x - 1) = -2", explanation: "Both composites are linear with the same gradient \\(6\\), but constants \\(-3\\) and \\(-1\\) — the difference is the constant \\(-2\\). Order matters: \\(fg \\ne gf\\)." } ], finalAnswer: "\\( fg(x) = 6x - 3 \\); \\( gf(x) = 6x - 1 \\)." } },
  { id: "y2fg3-053", topicRef: "y2fg3", topicTitle: "Composite Functions 52", difficulty: "Challenge", questionText: "\\( f(x) = ax + b \\) and \\( g(x) = bx + a \\), both with \\(x \\in \\mathbb R\\) (\\(a, b\\) constants). Find all conditions on \\(a\\) and \\(b\\) such that \\( fg(x) = gf(x) \\) holds for every real \\(x\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(fg(x)\\).", workingLatex: "fg(x) = a(bx + a) + b = abx + a^2 + b", explanation: "Apply \\(g\\) first, then \\(f\\)." }, { stepNumber: 2, description: "Form \\(gf(x)\\).", workingLatex: "gf(x) = b(ax + b) + a = abx + b^2 + a", explanation: "" }, { stepNumber: 3, description: "Match coefficients.", workingLatex: "abx + (a^2 + b) = abx + (b^2 + a) \\Rightarrow a^2 + b = b^2 + a", explanation: "The \\(x\\)-coefficients (both \\(ab\\)) match automatically; the constants give one equation." }, { stepNumber: 4, description: "Rearrange.", workingLatex: "a^2 - b^2 = a - b \\Rightarrow (a - b)(a + b) = (a - b)", explanation: "Difference of squares on the left." }, { stepNumber: 5, description: "Factor and split into cases.", workingLatex: "(a - b)(a + b - 1) = 0", explanation: "" }, { stepNumber: 6, description: "Read off both possibilities.", workingLatex: "a = b \\;\\;\\text{ or }\\;\\; a + b = 1", explanation: "The first case makes \\(f\\) and \\(g\\) identical; the second is the non-trivial condition." } ], finalAnswer: "\\( a = b \\) or \\( a + b = 1 \\)." } },
  { id: "y2fg3-054", topicRef: "y2fg3", topicTitle: "Composite Functions 53", difficulty: "Standard", questionText: "For \\(f(x) = \\tfrac{1}{x+1}\\) \\((x \\ne -1)\\) and \\(g(x) = x^2\\), find \\(fg(x)\\) and state its domain.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["composite", "domain", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g(x) = x^2\\) into \\(f\\).", workingLatex: "fg(x) = f(x^2)", explanation: "Apply \\(g\\) first (right-to-left), then feed the output into \\(f\\)." }, { stepNumber: 2, description: "Replace the variable in \\(f\\)'s definition.", workingLatex: "f(x^2) = \\tfrac{1}{x^2 + 1}", explanation: "Where \\(f\\) had \\(\\tfrac{1}{x + 1}\\), replace \\(x\\) by \\(x^2\\)." }, { stepNumber: 3, description: "Check that the denominator never vanishes.", workingLatex: "x^2 + 1 \\ge 1 > 0 \\text{ for all } x \\in \\mathbb R", explanation: "Since \\(x^2 \\ge 0\\), adding 1 gives at least 1. The denominator is strictly positive everywhere — \\(g\\) never sends \\(x\\) to the excluded value \\(-1\\)." }, { stepNumber: 4, description: "State the domain.", workingLatex: "\\text{Domain: } x \\in \\mathbb R", explanation: "No exclusions: the composite is defined for every real \\(x\\)." } ], finalAnswer: "\\( fg(x) = \\tfrac{1}{x^2 + 1} \\), defined for all real \\(x\\)." } },
  { id: "y2fg3-055", topicRef: "y2fg3", topicTitle: "Composite Functions 54", difficulty: "Challenge", questionText: "\\( f(x) = 2x + 3 \\), \\(x \\in \\mathbb R\\). Solve \\( fff(x) = ff(x) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(ff(x)\\).", workingLatex: "ff(x) = 2(2x + 3) + 3 = 4x + 9", explanation: "Substitute \\(f\\) into itself once." }, { stepNumber: 2, description: "Form \\(fff(x)\\).", workingLatex: "fff(x) = f(ff(x)) = 2(4x + 9) + 3 = 8x + 21", explanation: "Apply \\(f\\) one more time to the result of \\(ff\\)." }, { stepNumber: 3, description: "Set equal.", workingLatex: "8x + 21 = 4x + 9", explanation: "" }, { stepNumber: 4, description: "Solve the linear equation.", workingLatex: "4x = -12 \\Rightarrow x = -3", explanation: "Subtract \\(4x\\) from both sides, then divide by 4. Check: \\(ff(-3) = -12 + 9 = -3\\); \\(fff(-3) = -24 + 21 = -3\\). Both equal \\(-3\\) (a fixed point of \\(f\\))." } ], finalAnswer: "\\( x = -3 \\)." } },
  { id: "y2fg3-056", topicRef: "y2fg3", topicTitle: "Composite Functions 55", difficulty: "Challenge", questionText: "\\( f(x) = (x + a)^2 \\), \\(x \\in \\mathbb R\\), and \\( g(x) = x - 1 \\), where \\(a\\) is a constant. Given that the minimum value of \\( fg(x) \\) is 0 and is attained at \\(x = 3\\), find \\(a\\), and hence solve \\( fg(x) = 4 \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "solve", "quadratic"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite.", workingLatex: "fg(x) = ((x - 1) + a)^2 = (x - 1 + a)^2", explanation: "Substitute \\(g\\) into \\(f\\)." }, { stepNumber: 2, description: "Identify the location of the minimum.", workingLatex: "(x - 1 + a)^2 = 0 \\iff x = 1 - a", explanation: "A squared quantity attains its minimum value 0 where the bracket is zero." }, { stepNumber: 3, description: "Match to the given minimum location.", workingLatex: "1 - a = 3 \\Rightarrow a = -2", explanation: "" }, { stepNumber: 4, description: "Write the composite explicitly.", workingLatex: "fg(x) = (x - 3)^2", explanation: "" }, { stepNumber: 5, description: "Solve \\(fg(x) = 4\\).", workingLatex: "(x - 3)^2 = 4 \\Rightarrow x - 3 = \\pm 2", explanation: "Take square roots; both branches give valid solutions." }, { stepNumber: 6, description: "Read off the two solutions.", workingLatex: "x = 5 \\;\\;\\text{ or }\\;\\; x = 1", explanation: "" } ], finalAnswer: "\\( a = -2 \\); \\( x = 1 \\) or \\( x = 5 \\)." } },
  { id: "y2fg3-057", topicRef: "y2fg3", topicTitle: "Composite Functions 56", difficulty: "Challenge", questionText: "\\( f(x) = \\log_3 x \\) \\((x > 0)\\) and \\( g(x) = x^2 + ax \\), where \\(a\\) is a constant. Given that \\( fg(3) = 3 \\), find \\(a\\), and hence solve \\( fg(x) = 2 \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "parameter", "solve", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Translate \\(fg(3) = 3\\) into an equation.", workingLatex: "g(3) = 9 + 3a,\\;\\; \\log_3(9 + 3a) = 3", explanation: "Apply \\(g\\) at \\(x = 3\\) first." }, { stepNumber: 2, description: "Convert from log form.", workingLatex: "9 + 3a = 3^3 = 27 \\Rightarrow 3a = 18 \\Rightarrow a = 6", explanation: "\\(\\log_3 y = 3 \\iff y = 27\\)." }, { stepNumber: 3, description: "Write the general composite.", workingLatex: "g(x) = x^2 + 6x,\\;\\; fg(x) = \\log_3(x^2 + 6x)", explanation: "Domain: \\(x^2 + 6x > 0 \\iff x(x + 6) > 0 \\iff x < -6 \\text{ or } x > 0\\)." }, { stepNumber: 4, description: "Set equal to 2 and convert.", workingLatex: "\\log_3(x^2 + 6x) = 2 \\Rightarrow x^2 + 6x = 9", explanation: "" }, { stepNumber: 5, description: "Solve the quadratic.", workingLatex: "x^2 + 6x - 9 = 0 \\Rightarrow x = \\tfrac{-6 \\pm \\sqrt{36 + 36}}{2} = -3 \\pm 3\\sqrt{2}", explanation: "Quadratic formula; \\(\\sqrt{72} = 6\\sqrt{2}\\)." }, { stepNumber: 6, description: "Check both roots against the domain.", workingLatex: "-3 + 3\\sqrt{2} \\approx 1.24 > 0\\;\\checkmark;\\quad -3 - 3\\sqrt{2} \\approx -7.24 < -6\\;\\checkmark", explanation: "Both solutions lie inside the domain, so both are valid." } ], finalAnswer: "\\( a = 6 \\); \\( x = -3 + 3\\sqrt{2} \\) or \\( x = -3 - 3\\sqrt{2} \\)." } },
  { id: "y2fg3-058", topicRef: "y2fg3", topicTitle: "Composite Functions 57", difficulty: "Challenge", questionText: "\\( f(x) = \\cos x \\) and \\( g(x) = 2x + \\tfrac{\\pi}{3} \\). Solve \\( fg(x) = -\\tfrac{1}{2} \\) on the interval \\(0 \\le x \\le \\pi\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite.", workingLatex: "fg(x) = \\cos\\!\\left(2x + \\tfrac{\\pi}{3}\\right)", explanation: "Substitute \\(g\\) as the argument of cosine." }, { stepNumber: 2, description: "Translate the domain to the argument's range.", workingLatex: "0 \\le x \\le \\pi \\Rightarrow \\tfrac{\\pi}{3} \\le 2x + \\tfrac{\\pi}{3} \\le \\tfrac{7\\pi}{3}", explanation: "Let \\(\\theta = 2x + \\tfrac{\\pi}{3}\\) — this is the interval over which we need to solve \\(\\cos\\theta = -\\tfrac{1}{2}\\)." }, { stepNumber: 3, description: "List all \\(\\theta\\) in this range with \\(\\cos\\theta = -\\tfrac{1}{2}\\).", workingLatex: "\\theta = \\tfrac{2\\pi}{3},\\; \\tfrac{4\\pi}{3}", explanation: "Next candidates \\(\\tfrac{2\\pi}{3} + 2\\pi = \\tfrac{8\\pi}{3}\\) and \\(\\tfrac{4\\pi}{3} + 2\\pi\\) exceed \\(\\tfrac{7\\pi}{3}\\)." }, { stepNumber: 4, description: "Back-substitute and solve.", workingLatex: "2x + \\tfrac{\\pi}{3} = \\tfrac{2\\pi}{3} \\Rightarrow x = \\tfrac{\\pi}{6};\\quad 2x + \\tfrac{\\pi}{3} = \\tfrac{4\\pi}{3} \\Rightarrow x = \\tfrac{\\pi}{2}", explanation: "Subtract \\(\\tfrac{\\pi}{3}\\) and halve in each case." } ], finalAnswer: "\\( x = \\tfrac{\\pi}{6} \\) or \\( x = \\tfrac{\\pi}{2} \\)." } },
  { id: "y2fg3-059", topicRef: "y2fg3", topicTitle: "Composite Functions 58", difficulty: "Standard", questionText: "If \\( f(x) = x^2 - 2 \\), find \\( ff(x) \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Write \\(ff(x)\\) as \\(f(f(x))\\).", workingLatex: "ff(x) = f(x^2 - 2)", explanation: "Substitute \\(f(x) = x^2 - 2\\) back in as the new input." }, { stepNumber: 2, description: "Apply \\(f\\) to \\(x^2 - 2\\) (square it then subtract 2).", workingLatex: "f(x^2 - 2) = (x^2 - 2)^2 - 2", explanation: "" }, { stepNumber: 3, description: "Expand the square.", workingLatex: "(x^2 - 2)^2 = x^4 - 4x^2 + 4", explanation: "Standard expansion: \\((a - b)^2 = a^2 - 2ab + b^2\\) with \\(a = x^2\\), \\(b = 2\\)." }, { stepNumber: 4, description: "Subtract 2 to finish.", workingLatex: "x^4 - 4x^2 + 4 - 2 = x^4 - 4x^2 + 2", explanation: "" } ], finalAnswer: "\\( ff(x) = x^4 - 4x^2 + 2 \\)." } },
  { id: "y2fg3-060", topicRef: "y2fg3", topicTitle: "Composite Functions 17", difficulty: "Foundation", questionText: "If \\( f(x) = x + 1 \\), find \\( f^5(x) \\) (the function composed with itself five times).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Compute the first few iterates to spot the pattern.", workingLatex: "f^2(x) = f(x + 1) = (x + 1) + 1 = x + 2", explanation: "Each application of \\(f\\) adds 1 to the running input." }, { stepNumber: 2, description: "Continue the pattern.", workingLatex: "f^3(x) = x + 3,\\;\\; f^4(x) = x + 4,\\;\\; \\ldots", explanation: "After \\(n\\) applications the constant has accumulated to \\(n\\)." }, { stepNumber: 3, description: "Generalise and apply to \\(n = 5\\).", workingLatex: "f^n(x) = x + n \\Rightarrow f^5(x) = x + 5", explanation: "By induction, iterating \\(f\\) \\(n\\) times yields \\(x + n\\)." } ], finalAnswer: "\\( f^5(x) = x + 5 \\)." } },
  { id: "y2fg3-061", topicRef: "y2fg3", topicTitle: "Composite Functions 59", difficulty: "Standard", questionText: "With \\( f(x) = x + 1 \\) and \\( g(x) = 2x - 3 \\), solve \\(fg(x) = 5\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["composite", "solve"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(g\\) into \\(f\\).", workingLatex: "fg(x) = f(2x - 3) = (2x - 3) + 1", explanation: "Apply \\(g\\) first; \\(f\\) then adds 1 to the result." }, { stepNumber: 2, description: "Simplify the composite.", workingLatex: "(2x - 3) + 1 = 2x - 2", explanation: "Combine the constants \\(-3 + 1 = -2\\)." }, { stepNumber: 3, description: "Set equal to 5.", workingLatex: "2x - 2 = 5", explanation: "" }, { stepNumber: 4, description: "Solve for \\(x\\).", workingLatex: "2x = 7 \\Rightarrow x = \\tfrac{7}{2}", explanation: "Add 2 to both sides, then divide by 2. Check: \\(g(\\tfrac{7}{2}) = 7 - 3 = 4\\); \\(f(4) = 5\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = \\tfrac{7}{2} \\)." } },
  // ── Range of composite ────
  { id: "y2fg3-062", topicRef: "y2fg3", topicTitle: "Composite Functions 60", difficulty: "Challenge", questionText: "\\( f(x) = \\dfrac{1}{x} \\) \\((x \\ne 0)\\) and \\( g(x) = x^2 - 4 \\), \\(x \\in \\mathbb R\\). Find the largest possible domain and the range of \\( fg(x) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "domain", "range", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the composite.", workingLatex: "fg(x) = \\tfrac{1}{x^2 - 4}", explanation: "Substitute \\(g\\) into \\(f\\)." }, { stepNumber: 2, description: "Find the domain.", workingLatex: "x^2 - 4 \\ne 0 \\Rightarrow x \\ne \\pm 2", explanation: "Composite is undefined where the inner expression hits 0." }, { stepNumber: 3, description: "Analyse the outer branches \\(|x| > 2\\).", workingLatex: "x^2 - 4 \\in (0, \\infty) \\Rightarrow fg(x) \\in (0, \\infty)", explanation: "Inner expression takes all positive values: close to 0 as \\(|x| \\to 2^+\\), large as \\(|x| \\to \\infty\\). Reciprocal of \\((0, \\infty)\\) is \\((0, \\infty)\\)." }, { stepNumber: 4, description: "Analyse the inner region \\(|x| < 2\\).", workingLatex: "-2 < x < 2 \\Rightarrow x^2 \\in [0, 4) \\Rightarrow x^2 - 4 \\in [-4, 0)", explanation: "Inner expression ranges from \\(-4\\) (at \\(x = 0\\)) up to (but not including) 0." }, { stepNumber: 5, description: "Reciprocate on this region.", workingLatex: "fg(x) \\in \\left(-\\infty, -\\tfrac{1}{4}\\right]", explanation: "Reciprocal of \\([-4, 0)\\) is \\((-\\infty, -\\tfrac{1}{4}]\\); maximum value \\(-\\tfrac{1}{4}\\) attained at \\(x = 0\\), infimum \\(-\\infty\\) approached as \\(|x| \\to 2^-\\)." }, { stepNumber: 6, description: "Combine for the full range.", workingLatex: "\\text{Range: } \\left(-\\infty, -\\tfrac{1}{4}\\right] \\cup (0, \\infty)", explanation: "Union of the two sub-ranges from the two regions of the domain." } ], finalAnswer: "Domain: \\( x \\ne \\pm 2 \\); range: \\( y \\le -\\tfrac{1}{4} \\) or \\( y > 0 \\)." } },
  // ── Multi-step composition puzzle ────
  { id: "y2fg3-063", topicRef: "y2fg3", topicTitle: "Composite Functions 61", difficulty: "Standard", questionText: "Give an example of two functions \\(f, g\\) where \\(fg \\ne gf\\), and demonstrate that they differ.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Choose a specific pair.", workingLatex: "f(x) = x^2,\\;\\; g(x) = x + 1", explanation: "Any pair where one function is non-linear typically does the job — non-linear operations don't generally commute with shifts." }, { stepNumber: 2, description: "Form \\(fg(x)\\).", workingLatex: "fg(x) = f(x + 1) = (x + 1)^2 = x^2 + 2x + 1", explanation: "Apply \\(g\\) first to get \\(x + 1\\); then square." }, { stepNumber: 3, description: "Form \\(gf(x)\\).", workingLatex: "gf(x) = g(x^2) = x^2 + 1", explanation: "Apply \\(f\\) first to get \\(x^2\\); then add 1." }, { stepNumber: 4, description: "Compare via subtraction.", workingLatex: "fg(x) - gf(x) = (x^2 + 2x + 1) - (x^2 + 1) = 2x", explanation: "The difference is the simple expression \\(2x\\), making it easy to see when the two agree." }, { stepNumber: 5, description: "Identify exactly when they agree.", workingLatex: "2x = 0 \\iff x = 0", explanation: "Two composites agree only at \\(x = 0\\); elsewhere they differ. So \\(fg \\ne gf\\) as functions." } ], finalAnswer: "e.g. \\(f(x) = x^2\\), \\(g(x) = x + 1\\): \\(fg(x) - gf(x) = 2x\\), which is non-zero for every \\(x \\ne 0\\)." } },
  // ── Algebraic composite identities ────
  { id: "y2fg3-064", topicRef: "y2fg3", topicTitle: "Composite Functions 18", difficulty: "Foundation", questionText: "Explain the notation \\( (f \\circ g)(x) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["composite", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "State the definition.", workingLatex: "(f \\circ g)(x) = f(g(x))", explanation: "The small circle \\(\\circ\\) denotes function composition: it pairs an outer function (left) with an inner function (right)." }, { stepNumber: 2, description: "Describe the order of operations.", workingLatex: "x \\xrightarrow{\\;g\\;} g(x) \\xrightarrow{\\;f\\;} f(g(x))", explanation: "Apply \\(g\\) first (the function on the right), then apply \\(f\\) to that result. Read \\(f \\circ g\\) right-to-left." }, { stepNumber: 3, description: "State the domain requirement.", workingLatex: "g(x) \\in \\text{dom}(f)", explanation: "For \\((f \\circ g)(x)\\) to be defined at \\(x\\), the output \\(g(x)\\) must lie in the domain of \\(f\\)." }, { stepNumber: 4, description: "Note that composition is non-commutative in general.", workingLatex: "(f \\circ g)(x) \\ne (g \\circ f)(x) \\text{ in general}", explanation: "Swapping the order produces a different composite — order matters. (Commutativity is the exception, not the rule.)" } ], finalAnswer: "\\((f \\circ g)(x) = f(g(x))\\) — apply \\(g\\) first, then \\(f\\), with \\(g(x)\\) required to lie in \\(\\text{dom}(f)\\)." } },
  { id: "y2fg3-065", topicRef: "y2fg3", topicTitle: "Composite Functions 19", difficulty: "Foundation", questionText: "Is composition of functions associative? State the identity.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["composite", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the question: is bracketing of three composites significant?", workingLatex: "((f \\circ g) \\circ h)(x) \\;\\text{vs.}\\; (f \\circ (g \\circ h))(x)", explanation: "Two ways to bracket: compose \\(f \\circ g\\) first then apply to \\(h\\), or compose \\(g \\circ h\\) first then apply \\(f\\)." }, { stepNumber: 2, description: "Unpack the left bracketing.", workingLatex: "((f \\circ g) \\circ h)(x) = (f \\circ g)(h(x)) = f(g(h(x)))", explanation: "Apply \\(h\\) first, then the composite \\(f \\circ g\\) to its output." }, { stepNumber: 3, description: "Unpack the right bracketing.", workingLatex: "(f \\circ (g \\circ h))(x) = f((g \\circ h)(x)) = f(g(h(x)))", explanation: "Apply \\(g \\circ h\\) first (so \\(h\\) then \\(g\\)), then \\(f\\) — same chain of three applications." }, { stepNumber: 4, description: "Conclude.", workingLatex: "(f \\circ g) \\circ h = f \\circ (g \\circ h)", explanation: "Both expressions reduce to the function \\(x \\mapsto f(g(h(x)))\\). Composition is associative — bracket placement doesn't change the result (unlike commutativity, which generally fails)." } ], finalAnswer: "Yes; \\((f \\circ g) \\circ h = f \\circ (g \\circ h)\\) — both equal the function \\(x \\mapsto f(g(h(x)))\\)." } },
  // ── More pairs ────
  { id: "y2fg3-066", topicRef: "y2fg3", topicTitle: "Composite Functions 68", difficulty: "Challenge", questionText: "\\( f(x) = x^2 - 1 \\) and \\( g(x) = \\sqrt{x} \\) \\((x \\ge 0)\\). Solve the equation \\( fg(x) = gf(x) \\), stating any domain restrictions.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "domain"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\( fg(x) \\).", workingLatex: "fg(x) = (\\sqrt{x})^2 - 1 = x - 1 \\;\\;(x \\ge 0)", explanation: "Defined for all \\(x \\ge 0\\)." }, { stepNumber: 2, description: "Form \\( gf(x) \\) and determine its domain.", workingLatex: "gf(x) = \\sqrt{x^2 - 1}", explanation: "Requires \\(x^2 - 1 \\ge 0\\), i.e. \\(|x| \\ge 1\\). Combined with \\(x \\ge 0\\) (so both composites are defined), the common domain is \\(x \\ge 1\\)." }, { stepNumber: 3, description: "Set the two equal on \\(x \\ge 1\\).", workingLatex: "x - 1 = \\sqrt{x^2 - 1}", explanation: "Both sides are non-negative on this domain, so we can square." }, { stepNumber: 4, description: "Square both sides.", workingLatex: "(x - 1)^2 = x^2 - 1 \\Rightarrow x^2 - 2x + 1 = x^2 - 1", explanation: "" }, { stepNumber: 5, description: "Simplify and solve.", workingLatex: "-2x + 1 = -1 \\Rightarrow 2x = 2 \\Rightarrow x = 1", explanation: "Check: at \\(x = 1\\), \\(fg(1) = 0 = gf(1)\\). \\(\\checkmark\\)" } ], finalAnswer: "\\( x = 1 \\)." } },
  { id: "y2fg3-067", topicRef: "y2fg3", topicTitle: "Composite Functions 69", difficulty: "Challenge", questionText: "\\( f(x) = 3x + 2 \\) and \\( g(x) = ax + b \\), both with \\(x \\in \\mathbb R\\) (\\(a, b\\) constants). Given that \\( fg(x) = 6x + 5 \\) for all \\(x\\), find the values of \\(a\\) and \\(b\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "parameter"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\( fg(x) \\).", workingLatex: "fg(x) = f(ax + b) = 3(ax + b) + 2 = 3ax + (3b + 2)", explanation: "Substitute \\(g\\) into \\(f\\) and collect like terms." }, { stepNumber: 2, description: "Equate to \\(6x + 5\\) for all \\(x\\).", workingLatex: "3ax + (3b + 2) = 6x + 5", explanation: "Two linear polynomials agree for all \\(x\\) iff their coefficients match." }, { stepNumber: 3, description: "Match \\(x\\)-coefficients.", workingLatex: "3a = 6 \\Rightarrow a = 2", explanation: "" }, { stepNumber: 4, description: "Match constants.", workingLatex: "3b + 2 = 5 \\Rightarrow 3b = 3 \\Rightarrow b = 1", explanation: "" } ], finalAnswer: "\\( a = 2,\\; b = 1 \\)." } },
  { id: "y2fg3-068", topicRef: "y2fg3", topicTitle: "Composite Functions 62", difficulty: "Standard", questionText: "If \\(f(x) = 1 - x\\), find \\(ff(x)\\) and comment on the result.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["composite", "self-inverse"], workedSolution: { steps: [ { stepNumber: 1, description: "Unpack the notation.", workingLatex: "ff(x) = f(f(x))", explanation: "Two consecutive applications of \\(f\\): first \\(f(x)\\), then \\(f\\) of that result." }, { stepNumber: 2, description: "Substitute the inner application.", workingLatex: "ff(x) = f(1 - x)", explanation: "Replace the inner \\(f(x)\\) by its definition \\(1 - x\\)." }, { stepNumber: 3, description: "Apply \\(f\\) to the new input.", workingLatex: "f(1 - x) = 1 - (1 - x)", explanation: "\\(f\\) replaces its argument by \\(1 - (\\text{argument})\\)." }, { stepNumber: 4, description: "Simplify.", workingLatex: "1 - (1 - x) = 1 - 1 + x = x", explanation: "Distribute the minus through the bracket and cancel." }, { stepNumber: 5, description: "Interpret.", workingLatex: "ff = \\text{identity} \\Rightarrow f = f^{-1}", explanation: "If applying \\(f\\) twice returns the input, then \\(f\\) undoes itself: \\(f\\) is its own inverse (self-inverse). Geometrically: the graph \\(y = 1 - x\\) is symmetric in the line \\(y = x\\)." } ], finalAnswer: "\\( ff(x) = x \\) — \\(f\\) is self-inverse (its own inverse)." } },
  { id: "y2fg3-069", topicRef: "y2fg3", topicTitle: "Composite Functions 70", difficulty: "Challenge", questionText: "\\( f(x) = ax^2 + bx \\) and \\( g(x) = x - 1 \\), both with \\(x \\in \\mathbb R\\) (\\(a, b\\) constants). Given \\( fg(2) = 0 \\) and \\( fg(3) = 18 \\), find the values of \\(a\\) and \\(b\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "parameter"], workedSolution: { steps: [ { stepNumber: 1, description: "Translate \\( fg(2) = 0 \\) into a condition.", workingLatex: "g(2) = 1,\\;\\; fg(2) = a(1)^2 + b(1) = a + b = 0", explanation: "Apply \\(g\\) first to get \\(g(2) = 1\\); then \\(f(1) = a + b\\)." }, { stepNumber: 2, description: "Translate \\( fg(3) = 18 \\) similarly.", workingLatex: "g(3) = 2,\\;\\; fg(3) = 4a + 2b = 18 \\Rightarrow 2a + b = 9", explanation: "\\(f(2) = 4a + 2b\\); divide by 2 for a cleaner equation." }, { stepNumber: 3, description: "Subtract to eliminate \\(b\\).", workingLatex: "(2a + b) - (a + b) = 9 - 0 \\Rightarrow a = 9", explanation: "" }, { stepNumber: 4, description: "Back-substitute for \\(b\\).", workingLatex: "9 + b = 0 \\Rightarrow b = -9", explanation: "" } ], finalAnswer: "\\( a = 9,\\; b = -9 \\)." } },
  { id: "y2fg3-070", topicRef: "y2fg3", topicTitle: "Composite Functions 71", difficulty: "Challenge", questionText: "\\( f(x) = x^2 - 3 \\), \\(x \\in \\mathbb R\\), and \\( g(x) = \\dfrac{1}{x - k} \\) \\((x \\ne k)\\), where \\(k\\) is a constant. Given that \\( gf(2) = 1 \\), find \\(k\\), and hence solve the equation \\( gf(x) = -1 \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["composite", "solve", "parameter", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Use \\( gf(2) = 1 \\) to find \\(k\\).", workingLatex: "f(2) = 4 - 3 = 1,\\;\\; gf(2) = \\tfrac{1}{1 - k} = 1", explanation: "Apply \\(f\\) first, then \\(g\\)." }, { stepNumber: 2, description: "Solve for \\(k\\).", workingLatex: "1 - k = 1 \\Rightarrow k = 0", explanation: "So \\(g(x) = \\tfrac{1}{x}\\), defined for \\(x \\ne 0\\)." }, { stepNumber: 3, description: "Form \\( gf(x) \\) in general.", workingLatex: "gf(x) = \\tfrac{1}{x^2 - 3}", explanation: "Substitute \\(f(x) = x^2 - 3\\) into \\(g\\). Domain restriction: \\(x^2 - 3 \\ne 0\\), i.e. \\(x \\ne \\pm\\sqrt{3}\\)." }, { stepNumber: 4, description: "Set equal to \\(-1\\).", workingLatex: "\\tfrac{1}{x^2 - 3} = -1", explanation: "" }, { stepNumber: 5, description: "Reciprocate and solve.", workingLatex: "x^2 - 3 = -1 \\Rightarrow x^2 = 2 \\Rightarrow x = \\pm \\sqrt{2}", explanation: "Both values are non-zero and \\(\\ne \\pm\\sqrt{3}\\), so both are valid." } ], finalAnswer: "\\( k = 0 \\); \\( x = \\pm \\sqrt{2} \\)." } },
  { id: "y2fg3-071", topicRef: "y2fg3", topicTitle: "Composite Functions 63", difficulty: "Standard", questionText: "Explain why \\(fg(x)\\) might not be defined for some \\(x\\), giving a concrete example.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["composite", "theory", "domain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the existence requirement.", workingLatex: "fg(x) = f(g(x)) \\text{ defined} \\iff g(x) \\in \\text{dom}(f)", explanation: "To evaluate \\(f(g(x))\\), we first compute \\(g(x)\\) and then feed it into \\(f\\). For the second step to make sense, \\(g(x)\\) must be a legitimate input to \\(f\\)." }, { stepNumber: 2, description: "Identify the failure mode.", workingLatex: "g(x) \\notin \\text{dom}(f) \\Rightarrow fg(x) \\text{ undefined at that } x", explanation: "If at some input \\(x\\), \\(g\\) produces a value outside \\(\\text{dom}(f)\\), the second-stage application fails — the composite is undefined at that \\(x\\)." }, { stepNumber: 3, description: "Set up a concrete example.", workingLatex: "f(x) = \\sqrt{x}\\;(x \\ge 0),\\;\\; g(x) = x - 3 \\;(x \\in \\mathbb R)", explanation: "\\(g\\) has the full real line as domain; \\(f\\) only accepts non-negative inputs." }, { stepNumber: 4, description: "Form the composite and find where it fails.", workingLatex: "fg(x) = \\sqrt{x - 3} \\text{ needs } x - 3 \\ge 0 \\Rightarrow x \\ge 3", explanation: "When \\(x < 3\\), \\(g(x) = x - 3 < 0\\) lies outside \\(\\text{dom}(f)\\); the square root would not be real. The composite's natural domain is \\(x \\ge 3\\) — strictly smaller than \\(\\text{dom}(g)\\)." } ], finalAnswer: "\\(fg(x)\\) is defined only when \\(g(x)\\) lies in the domain of \\(f\\); e.g. with \\(f = \\sqrt{\\;}\\) and \\(g(x) = x - 3\\), \\(fg(x) = \\sqrt{x - 3}\\) is only defined for \\(x \\ge 3\\)." } },
];
